window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[75]={"id":"075","numero":75,"titre":"Addiction au tabac","objectifs":[{"id":"75-1","rang":"A","rubrique":"Définition","titre":"Connaître les principaux risques liés au tabagisme actif, au tabagisme passif, et au tabagisme in utero","contenu":"<div class=\"notion-course\"><p>Le <span>tabagisme</span> est l'inhalation de la fumée de <span>tabac</span>, volontaire ou involontaire. Il n'existe <strong>aucun seuil de consommation sans risque</strong> — <span>les</span> complications concernent les trois modalités d'exposition.</p>\n      <table>\n        <thead><tr><th>Exposition</th><th>Principaux risques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span>Tabagisme actif</span><br>(le fumeur inhale sa propre fumée)</td>\n            <td>\n              <strong>Cancers :</strong> <span>poumon</span> ; voies aéro-digestives supérieures ; <span class=\"nc-red\">vessie</span> ; <span class=\"nc-red\">pancréas</span><br>\n              <strong>Cardiovasculaire :</strong> <span>HTA</span> ; <span>infarctus du myocarde</span> ; AOMI ; <span>AVC</span><br>\n              <strong>Respiratoire :</strong> <span><span class=\"nc-orange_bg\">BPCO</span></span> ; <span class=\"nc-orange_bg\">emphysème</span><br>\n              <strong>Reproduction :</strong> baisse de la fertilité ; troubles de la <span><span class=\"nc-green nc-bold\">grossesse</span></span>\n            </td>\n          </tr>\n          <tr>\n            <td><span>Tabagisme passif</span><br>(<span class=\"nc-red nc-bold\">non-fumeur</span> exposé à la fumée ambiante)</td>\n            <td>\n              <strong>Adulte :</strong> <span class=\"nc-red_bg\">cancer pulmonaire</span> (RR <span>+ 25 %</span>) ; décès cardiovasculaire (RR <span>+ 20-30 %</span>) — risque présent <strong>même à faibles doses</strong><br>\n              <strong><span class=\"nc-red nc-bold\">Femme enceinte</span> :</strong> <span><span class=\"nc-red_bg\">RCIU</span></span> ; <span class=\"nc-red_bg\">accouchement prématuré</span><br>\n              <strong>Enfant / nourrisson :</strong> otites et <span class=\"nc-purple_bg\">infections</span> <span class=\"nc-purple_bg nc-bold\">ORL</span> ; <span class=\"nc-purple_bg\">infections</span> <span class=\"nc-purple_bg nc-bold\">pulmonaires</span> ; <span><span class=\"nc-orange_bg\">asthme</span></span> ; <span><span class=\"nc-red nc-bold\">mort subite du nourrisson</span></span>\n            </td>\n          </tr>\n          <tr>\n            <td><span>Tabagisme in utero</span><br>(exposition fœtale)</td>\n            <td>\n              <span>Fausse couche</span> ; mort fœtale in utero ; <span><span class=\"nc-red_bg\">rupture</span></span><span class=\"nc-red_bg\"> prématurée des membranes</span> ; <span class=\"nc-red_bg\">accouchement prématuré</span> ; <span><span class=\"nc-red_bg\">RCIU</span></span> ; <span><span class=\"nc-green nc-bold\">grossesse</span></span> extra-utérine ; <span class=\"nc-orange_bg\">placenta praevia</span> ; <span class=\"nc-orange_bg\">hématome rétroplacentaire</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Le <span>courant secondaire</span> (fumée s'échappant du bout incandescent de la c<span>iga</span>rette) est <strong>plus <span>toxique</span></strong> que le courant primaire <span class=\"nc-red_bg\">inhalé par le fumeur</span> : plus concentré en <span><span class=\"nc-yellow_bg\">monoxyde de carbone</span></span>, goudrons et cancérigènes, et non filtré.\n      </div></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details><details data-lisa-review=\"20261014\"><summary>Situations de départ LiSA vérifiées</summary><p>Attendus consultés sur LiSA 2026 le 14 octobre 2026, reformulés pour la révision.</p><ul><li><a href=\"https://livret.uness.fr/lisa/2026/Pr%C3%A9vention_des_risques_li%C3%A9s_au_tabac_SDD-314\" target=\"_blank\" rel=\"noopener noreferrer\">SDD 314 · Prévention des risques liés au tabac</a><ul><li>Évaluer exposition et dépendance, expliquer les risques actifs, passifs et pendant la grossesse ; chercher co-addictions et complications.</li><li>Adapter aides médicamenteuses et accompagnement, organiser le suivi et l’orientation ; prévenir l’initiation et les reprises.</li></ul></li><li><a href=\"https://livret.uness.fr/lisa/2026/Premi%C3%A8re_consultation_d%27addictologie_SDD-292\" target=\"_blank\" rel=\"noopener noreferrer\">SDD 292 · Première consultation d’addictologie</a><ul><li>Caractériser usage nocif, dépendance ou addiction comportementale selon la classification utilisée ; rechercher sevrage, complications et comorbidités.</li><li>Évaluer les conséquences familiales, sociales et professionnelles, fixer des objectifs partagés et orienter ou proposer une substitution selon indication.</li></ul></li><li><a href=\"https://livret.uness.fr/lisa/2026/Consultation_de_suivi_addictologie_SDD-293\" target=\"_blank\" rel=\"noopener noreferrer\">SDD 293 · Consultation de suivi addictologie</a><ul><li>Rechercher manque, nouveaux symptômes, complications et comorbidités ; apprécier efficacité, tolérance et qualité de vie.</li><li>Adapter prescription et accompagnement social ; la valorisation du stage inclut psychothérapie, entretien motivationnel et soutien des proches avec respect de la confidentialité.</li></ul></li></ul><p>Les liens ciblent les compétences pertinentes pour cet item ; ils ne signifient pas que la fiche couvre à elle seule toute la situation de départ.</p></details>","frequence":1},{"id":"75-2","rang":"A","rubrique":"Définition","titre":"Connaître les principaux types de dépendance entraînés par le tabac et la façon d’évaluer cette dépendance","contenu":"<div class=\"notion-course\"><p>Le <span>tabac</span> entraîne une <span><span class=\"nc-purple_bg\">dépendance</span></span> à plusieurs registres, qu'il faut tous évaluer. La <span><span class=\"nc-purple_bg\">dépendance</span> selon la CIM-10</span> est définie par la présence d'<span>≥ 3 manifestations</span> au cours de la dernière année.</p>\n      <table>\n        <thead><tr><th>Type de dépendance</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span>CIM-10</span><br>(<span>≥ 3</span> critères / <span>12 mois</span>)</td>\n            <td><span>Désir compulsif</span> de consommer ; difficultés à contrôler l'usage (début, quantité, arrêt) ; <span>syndrome de sevrage</span> à l'arrêt ; <span>tolérance</span> (augmentation des doses) ; désintérêt pour <span>les</span> autres plaisirs ; poursuite malgré les conséquences néfastes</td>\n          </tr>\n          <tr>\n            <td><span>Physique</span> (pharmacologique)</td>\n            <td>Liée directement à la <span>nicotine</span> : pic de concentration rapide vers le cerveau (« <strong><span class=\"nc-red nc-bold\">effet shoot</span></strong> ») ; fixation sur <span>les</span> <span><span class=\"nc-purple nc-bold\">récepteurs cholinergiques nicotiniques</span></span> ; stimulation du système de récompense par libération de <span>dopamine</span>. S'évalue par le <span><span class=\"nc-blue_bg\">test de Fagerström</span></span>.</td>\n          </tr>\n          <tr>\n            <td><span>Psychologique</span></td>\n            <td>Liée aux « effets positifs » associés à la c<span>iga</span>rette (<span class=\"nc-green nc-bold\">se relaxer</span>, <span class=\"nc-green nc-bold\">réfléchir</span>, <span class=\"nc-green nc-bold\">effet coupe-faim</span>). Reflétée par le <span><span class=\"nc-blue_bg nc-bold\">craving</span></span>.</td>\n          </tr>\n          <tr>\n            <td><span>Comportementale</span> (sociale)</td>\n            <td>Liée aux <span class=\"nc-yellow_bg nc-bold\">situations répétées associées à la c</span><span><span class=\"nc-yellow_bg nc-bold\">iga</span></span><span class=\"nc-yellow_bg nc-bold\">rette</span> (moments de convivialité ; association au café, à l'<span><span class=\"nc-red_bg\">alcool</span></span>, au <span class=\"nc-red_bg\">cannabis</span>) déclenchant une envie « réflexe ». Reflétée par le <span><span class=\"nc-blue_bg nc-bold\">craving</span></span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>L'<strong>évaluation</strong> de la <span class=\"nc-purple_bg\">dépendance</span> physique repose sur le <span><span class=\"nc-blue_bg\">test de Fagerström</span></span> ; <span>les</span> dépendances psychologique et comportementale s'apprécient sur la <span class=\"nc-blue_bg\">présence de </span><span><span class=\"nc-blue_bg\">craving</span></span>, qui est un <span>facteur de risque de rechute</span>. Le détail du test est développé dans les modalités de diagnostic de la <span class=\"nc-purple_bg\">dépendance</span>.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":3},{"id":"75-3","rang":"B","rubrique":"Définition","titre":"Connaître la définition de la cigarette électronique","contenu":"<div class=\"notion-course\"><h4>Un aérosol sans combustion du tabac</h4><p>Une <span class=\"nc-yellow_bg\">batterie</span> alimente une résistance qui chauffe un e-liquide : propylène glycol, glycérine, arômes et éventuellement nicotine. Il s’agit d’un aérosol, pas d’une simple vapeur d’eau. L’<span class=\"nc-green nc-bold\">absence de combustion</span> réduit l’exposition à de nombreux toxiques de la fumée ; elle ne prouve pas l’innocuité des substances inhalées ni de leur chauffage.</p><ul><li>Les liquides nicotinés entretiennent une dépendance ; toxicité possible en cas d’ingestion, particulièrement chez l’enfant.</li><li>Le vapotage n’est pas un médicament ni un <span class=\"nc-pink_bg\">traitement</span> remboursé ; les <span class=\"nc-pink\">substituts nicotiniques</span> restent la première proposition médicamenteuse.</li><li>Ne pas encourager son initiation chez un <span class=\"nc-red nc-bold\">non-fumeur</span> ou pendant la <span class=\"nc-green nc-bold\">grossesse</span>. Accompagner le fumeur qui l’utilise vers l’arrêt complet des cigarettes ; éviter la persistance du double usage.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://www.ameli.fr/assure/remboursements/rembourse/medicaments-vaccins-dispositifs-medicaux/prise-charge-substituts-nicotiniques\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · Prise en charge des substituts nicotiniques</a></li></ul><p></p></details>","frequence":0},{"id":"75-4","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la toxicité de la nicotine, des goudrons et de la fumée de tabac","contenu":"<div class=\"notion-course\"><h4>Dépendance et toxicité : distinguer les constituants</h4><table><thead><tr><th>Constituant</th><th>Effets</th></tr></thead><tbody><tr><td>Nicotine</td><td><span class=\"nc-yellow_bg nc-bold\">Dépendance</span> via les récepteurs nicotiniques ; effets sympathiques possibles (fréquence cardiaque, pression artérielle). Ce n’est pas le principal cancérigène du tabac.</td></tr><tr><td>Goudrons et autres cancérigènes</td><td>Hydrocarbures aromatiques, nitrosamines, <span class=\"nc-red_bg\">benzène</span>… : altérations cellulaires et cancérogenèse.</td></tr><tr><td><span class=\"nc-yellow_bg\">Monoxyde de carbone</span></td><td>Carboxyhémoglobine et diminution du transport d’oxygène.</td></tr><tr><td>Particules, oxydants et irritants</td><td>Inflammation, dysfonction endothéliale, thrombose et lésions respiratoires.</td></tr></tbody></table><div class=\"callout\"><p>Les <span class=\"nc-pink\">substituts nicotiniques</span> évitent les produits de combustion et sont beaucoup moins dangereux que continuer à fumer. « Moins dangereux » ne signifie pas « nicotine sans aucun effet ».</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":1},{"id":"75-5","rang":"B","rubrique":"Physiopathologie","titre":"Connaître le mécanisme d'atteinte artérielle (thrombogénicité, vasomotricité, inflammation)","contenu":"<div class=\"notion-course\"><h4>Mécanismes artériels convergents</h4><ul><li>Dysfonction endothéliale et <span class=\"nc-blue_bg\">altération de la</span> vasodilatation ; vasoconstriction et spasme possibles.</li><li>Activation <span class=\"nc-blue_bg nc-bold\">plaquettaire</span>, augmentation de la thrombogenicité <span class=\"nc-blue_bg\">et de la</span> <span class=\"nc-blue_bg nc-bold\">viscosité</span>.</li><li>Inflammation et stress oxydatif favorisant l’athérosclérose.</li><li>CO : hypoxie ; nicotine : stimulation sympathique. La fumée associe ces mécanismes et les risques ne se déduisent pas de la nicotine seule.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":1},{"id":"75-6","rang":"A","rubrique":"Epidémiologie","titre":"Connaître l’âge de début, le pourcentage de dépendants et la mortalité mondiale et française liée au tabac et les risques","contenu":"<div class=\"notion-course\"><h4>Repères à dater</h4><ul><li>L’initiation survient fréquemment à l’adolescence ; les valeurs 14–15 ans et « environ la moitié dépendants » du cours sont des ordres de grandeur historiques, variables selon population et définition.</li><li>Un fumeur régulier sur deux environ meurt d’une maladie liée au tabac ; le fardeau mondial se compte en millions de décès.</li><li>France : ancienne estimation de 75 000 décès attribuables en 2015 ; estimation actualisée d’environ 68 000 pour 2023.</li><li>Dose et surtout durée d’exposition influencent le risque. Ne pas appliquer à <span class=\"nc-yellow_bg nc-bold\">chaque</span> personne une règle universelle « doubler la durée multiplie par 16 à 23 ». Aucun seuil n’est sûr.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://www.santepubliquefrance.fr/tabac\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · Tabac : mortalité attribuable</a></li></ul><p></p></details>","frequence":0},{"id":"75-7","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les tendances épidémiologiques du tabagisme au cours du temps","contenu":"<div class=\"notion-course\"><h4>Tendance</h4><p>Baisse sur la dernière décennie, avec une stagnation ou remontée pendant certaines années de la crise sanitaire puis un recul. Ne pas présenter « ré-augmentation depuis 2020 » comme la tendance actuelle permanente.</p><p>Baromètre 2024, France hexagonale, 18–75 ans : 25,0 % fument, dont 18,2 % quotidiennement. Le quotidien reste plus fréquent chez les hommes (20,4 %) que chez les femmes (16,2 %). La méthode d’enquête a changé : comparer les années avec prudence.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://www.drogues.gouv.fr/sites/default/files/2025-10/Barom%C3%A8tre_Tabagisme_2024.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · Baromètre tabagisme 2024</a></li></ul><p></p></details>","frequence":0},{"id":"75-8","rang":"A","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie du tabagisme chez les hommes et les femmes","contenu":"<div class=\"notion-course\"><h4>Sexe et âge : même population pour comparer</h4><p>Baromètre 2024, France hexagonale, 18–75 ans : 25,0 % fument, dont 18,2 % quotidiennement. Le quotidien reste plus fréquent chez les hommes (20,4 %) que chez les femmes (16,2 %). La méthode d’enquête a changé : comparer les années avec prudence.</p><p>Les anciennes valeurs 33 %, 35 % et 25 % du cours provenaient de repères différents. Préciser année, tranche d’âge, territoire et consommation quotidienne ou occasionnelle.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://www.drogues.gouv.fr/sites/default/files/2025-10/Barom%C3%A8tre_Tabagisme_2024.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · Baromètre tabagisme 2024</a></li></ul><p></p></details>","frequence":0},{"id":"75-9","rang":"A","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie du tabagisme chez les jeunes","contenu":"<div class=\"notion-course\"><p>La consommation de <span>tabac</span> chez <span>les</span> jeunes est en <strong>baisse importante</strong>.</p>\n      <table>\n        <thead><tr><th>Population</th><th>Tendance</th></tr></thead>\n        <tbody>\n          <tr><td>Élèves de 3ᵉ — expérimentation</td><td><span>51,8 %</span> (2010) → <span>29,1 %</span> (2021)</td></tr>\n          <tr><td>Élèves de 3ᵉ — usage quotidien</td><td><span>15,6 %</span> (2010) → <span>3,7 %</span> (2021)</td></tr>\n          <tr><td><span>17 ans</span> — usage quotidien</td><td><span>32,4 %</span> (2014) → <span>25,1 %</span> (2017)</td></tr>\n          <tr><td><span class=\"nc-pink_bg\">C</span><span><span class=\"nc-pink_bg\">iga</span></span><span class=\"nc-pink_bg\">rette électronique</span> (3ᵉ)</td><td><span>34,2 %</span> d'expérimentateurs (2021)</td></tr>\n          <tr><td>Chicha (3ᵉ)</td><td>En recul : expérimentation <span>26,2 %</span> (2018) → <span>20 %</span> (2021)</td></tr>\n        </tbody>\n      </table></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"75-10","rang":"A","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie du tabagisme chez la femme enceinte","contenu":"<div class=\"notion-course\"><h4>Le dénominateur change l’interprétation</h4><p>« Environ une sur deux poursuit » concernait les femmes qui fumaient avant la <span class=\"nc-green nc-bold\">grossesse</span>, pas toutes les femmes enceintes. Dans l’enquête périnatale 2016 : 30,0 % fumaient avant, 16,2 % au troisième trimestre ; 45,8 % des fumeuses avaient arrêté. Ce sont des données datées.</p><p>Repérer sans culpabiliser, proposer l’arrêt et un soutien adapté ; jeunes femmes et situations sociales défavorisées nécessitent une attention particulière.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://beh.santepubliquefrance.fr/beh/2018/35-36/2018_35-36_2.html\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · Tabac pendant la grossesse, enquête 2016</a></li></ul><p></p></details>","frequence":0},{"id":"75-11","rang":"A","rubrique":"Epidémiologie","titre":"Connaître les modes de consommation du tabac","contenu":"<div class=\"notion-course\"><h4>Décrire précisément le produit et la voie</h4><table><thead><tr><th>Usage</th><th>Produits</th></tr></thead><tbody><tr><td>Fumée de combustion</td><td>Cigarettes manufacturées ou roulées, cigare, cigarillo, pipe, chicha.</td></tr><tr><td>Tabac chauffé</td><td>Tabac chauffé produisant un aérosol ; contient du tabac <span class=\"nc-blue_bg\">et de la</span> nicotine, expose à des toxiques, ne constitue pas un produit anodin.</td></tr><tr><td>Vapotage</td><td>Liquide avec ou sans nicotine ; ne contient généralement pas de feuille de tabac. Les dispositifs jetables sont distincts des rechargeables.</td></tr><tr><td>Voie nasale</td><td>Tabac à priser.</td></tr><tr><td>Voie buccale</td><td>Tabac à chiquer ou snus : absorption par la muqueuse, pas une consommation décrite comme ingestion alimentaire. Ne pas confondre avec les sachets nicotinés sans tabac.</td></tr></tbody></table><p>Le statut commercial dépend du produit et du pays ; les dispositifs de vapotage jetables sont interdits à la vente en France depuis 2025.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"75-12","rang":"A","rubrique":"Epidémiologie","titre":"Connaître l’ordre de grandeur du nombre de cas de cancer liés au tabac","contenu":"<div class=\"notion-course\"><h4>Incidence et mortalité par <span class=\"nc-green_bg\">cancer</span></h4><ul><li>Premier facteur de risque évitable de <span class=\"nc-green_bg\">cancer</span> : environ un cinquième des nouveaux cancers en France.</li><li>Repère INCa pour 2015 : environ 68 000 nouveaux cancers et 46 000 décès par <span class=\"nc-green_bg\">cancer</span> attribuables au tabac.</li><li>Le <span class=\"nc-green_bg\">cancer du</span> poumon représente la plus grande part de cette mortalité ; le chiffre du cours d’environ 32 000 décès <span class=\"nc-purple_bg nc-bold\">pulmonaires</span> doit rester rattaché à son estimation historique.</li><li>Ne pas confondre les 68 000 nouveaux cancers de 2015 avec les 68 000 décès toutes causes attribuables au tabac en 2023.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://www.cancer.fr/toute-l-information-sur-les-cancers/comprendre-les-cancers/les-facteurs-de-risque/barometre-cancer/tabac-et-cancer\" target=\"_blank\" rel=\"noopener noreferrer\">INCa · Tabac et cancer</a></li><li><a href=\"https://www.santepubliquefrance.fr/tabac\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · Tabac : mortalité attribuable</a></li></ul><p></p></details>","frequence":1},{"id":"75-13","rang":"A","rubrique":"Epidémiologie","titre":"Connaître la part du tabac dans la mortalité en France","contenu":"<div class=\"notion-course\"><h4>Première cause de mortalité évitable</h4><p>Santé publique France estime environ 68 000 décès attribuables au tabac en 2023, soit environ 11 % des décès. Le chiffre de 75 000 et les parts de 20 % chez les hommes / 7 % chez les femmes sont des repères antérieurs, à ne pas présenter comme une mesure 2026.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://www.santepubliquefrance.fr/tabac\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · Tabac : mortalité attribuable</a></li></ul><p></p></details>","frequence":0},{"id":"75-14","rang":"A","rubrique":"Epidémiologie","titre":"Connaître la mortalité liée au tabagisme actif","contenu":"<div class=\"notion-course\"><p>Un fumeur sur deux (<span>≈ 50 %</span>) mourra prématurément d'une maladie due au <span>tabac</span>. Répartition des causes de décès liées au <span>tabac</span> (2015) :</p>\n      <table>\n        <thead><tr><th>Cause</th><th>Décès / an</th></tr></thead>\n        <tbody>\n          <tr><td><span>Cancers</span></td><td><span>≈ 46 000</span> (dont ≈ 32 000 cancers du poumon)</td></tr>\n          <tr><td>Maladies cardiovasculaires</td><td><span>≈ 17 000</span> (environ 1/4)</td></tr>\n          <tr><td>Maladies respiratoires</td><td><span>≈ 12 000</span></td></tr>\n        </tbody>\n      </table><div class=\"callout\"><p>Les répartitions ci-dessus sont des repères de 2015. La nouvelle estimation globale est de 68 000 décès attribuables pour 2023 ; ne pas additionner des composantes de 2015 pour décrire 2023.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://www.santepubliquefrance.fr/tabac\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · Tabac : mortalité attribuable</a></li></ul><p></p></details>","frequence":0},{"id":"75-15","rang":"A","rubrique":"Epidémiologie","titre":"Connaître l’impact sur la mortalité cardiovasculaire","contenu":"<div class=\"notion-course\"><h4>Risque cardiovasculaire</h4><ul><li>Le tabac favorise infarctus, AOMI, AVC et anévrisme de l’aorte abdominale ; aucun multiplicateur unique « ×20 » ne décrit toutes les maladies cardiovasculaires.</li><li>Effet important même à faible consommation ; risque relatif particulièrement marqué chez le sujet jeune et interaction avec les autres facteurs de risque.</li><li>Les ordres de grandeur du cours (IDM autour de ×3, AVC autour de ×1,5–2) varient selon population et exposition.</li><li>Tabac et contraception estroprogestative augmentent surtout le risque artériel ; évaluer âge et facteurs associés avant prescription.</li><li>L’arrêt procure rapidement un bénéfice cardiovasculaire, même après un événement constitué.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":1},{"id":"75-16","rang":"A","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie du tabagisme et celles des principales maladies liées au tabac","contenu":"<div class=\"notion-course\"><h4>Trois groupes majeurs de maladies</h4><p>Baromètre 2024, France hexagonale, 18–75 ans : 25,0 % fument, dont 18,2 % quotidiennement. Le quotidien reste plus fréquent chez les hommes (20,4 %) que chez les femmes (16,2 %). La méthode d’enquête a changé : comparer les années avec prudence.</p><table><thead><tr><th>Groupe</th><th>Complications</th></tr></thead><tbody><tr><td>Cancers</td><td>Poumon, VADS, <span class=\"nc-red\">vessie</span> et autres localisations ; premier facteur évitable.</td></tr><tr><td>Cardiovasculaire</td><td>Infarctus, AVC, artériopathie périphérique et anévrisme.</td></tr><tr><td>Respiratoire</td><td><span class=\"nc-orange_bg\">BPCO</span>, <span class=\"nc-orange_bg\">emphysème</span>, <span class=\"nc-orange_bg\">bronchite chronique</span> et mauvais contrôle de l’<span class=\"nc-orange_bg\">asthme</span>.</td></tr></tbody></table></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://www.drogues.gouv.fr/sites/default/files/2025-10/Barom%C3%A8tre_Tabagisme_2024.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Santé publique France · Baromètre tabagisme 2024</a></li></ul><p></p></details>","frequence":0},{"id":"75-17","rang":"A","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie du tabagisme passif, les grandes notions de sur-risque","contenu":"<div class=\"notion-course\"><p>Le <span>tabagisme passif</span> (involontaire) augmente le risque de maladie <strong>même à faibles doses</strong> — il n'existe pas de seuil sans risque.</p>\n      <table>\n        <thead><tr><th>Population</th><th>Sur-risque</th></tr></thead>\n        <tbody>\n          <tr><td>Adulte — <span class=\"nc-red_bg\">cancer pulmonaire</span></td><td>RR augmenté de <span>≈ 25 %</span></td></tr>\n          <tr><td>Adulte — décès cardiovasculaire</td><td>RR augmenté de <span>≈ 20-30 %</span></td></tr>\n          <tr><td>Enfant / nourrisson</td><td><span class=\"nc-purple_bg\">Infections</span> <strong><span class=\"nc-purple_bg nc-bold\">ORL</span></strong> (<span><span class=\"nc-orange nc-bold\">otite</span></span>) ; <span class=\"nc-purple_bg\">infections</span> <strong><span class=\"nc-purple_bg nc-bold\">pulmonaires</span></strong> (<span class=\"nc-orange nc-bold\">bronchite</span>) ; <span><span class=\"nc-orange_bg\">asthme</span></span> ; <span><span class=\"nc-red nc-bold\">mort subite du nourrisson</span></span></td></tr>\n        </tbody>\n      </table></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"75-18","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les catégories socio-professionnelles (CSP) des fumeurs en France","contenu":"<div class=\"notion-course\"><p>Le <span>tabac</span> reste un puissant <strong>marqueur social</strong>.</p>\n      <ul>\n        <li><span>Prévalence</span> plus élevée chez <span>les</span> <span>chômeurs</span>.</li>\n        <li>En 2018 : plus le revenu augmente, plus la <span>prévalence</span> du <span>tabagisme</span> quotidien est <strong>basse</strong> (gradient social inverse).</li>\n        <li>La <span>prévalence</span> diminue néanmoins, y compris parmi <span>les</span> fumeurs les plus défavorisés.</li>\n      </ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"75-19","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir dépister la consommation de tabac","contenu":"<div class=\"notion-course\"><h4>Repérer et quantifier</h4><ol><li>Demander à <span class=\"nc-yellow_bg nc-bold\">chaque</span> patient s’il fume et préciser <span class=\"nc-yellow_bg nc-bold\">tous</span> les produits, y compris <span class=\"nc-red_bg\">cannabis</span> associé au tabac et vapotage.</li><li>Documenter <span class=\"nc-blue_bg\">âge de début</span>, durée, quantité actuelle et passée, périodes d’arrêt et contexte.</li><li>Cigarettes : <span class=\"nc-yellow_bg nc-bold\">paquets-années</span> = paquets de 20 par jour × années, en distinguant les différentes périodes.</li><li>Décrire les autres produits en quantité réelle et fréquence ; aucune équivalence universelle entre un joint, une chicha et un nombre de cigarettes ne résume leur toxicité.</li></ol><div class=\"callout\"><p>Le paquet-année résume l’exposition mais ne suffit pas à estimer le risque : durée, intensité et temps depuis l’arrêt comptent.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":1},{"id":"75-20","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités de diagnostic de la dépendance","contenu":"<div class=\"notion-course\"><p>Le diagnostic de <span class=\"nc-purple_bg\">dépendance</span> distingue trois registres. Environ <span>50 %</span> des fumeurs réguliers présentent des signes de <span class=\"nc-purple_bg\">dépendance</span>.</p>\n      <table>\n        <thead><tr><th>Registre</th><th>Outil de diagnostic</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"nc-purple_bg\">Dépendance</span> <strong>pharmacologique</strong></td><td><span class=\"nc-blue_bg\">Test de Fagerström</span>, complet ou simplifié.</td></tr>\n          <tr><td><span class=\"nc-purple_bg\">Dépendance</span> <strong>psychologique</strong> et <strong>comportementale</strong></td><td><span class=\"nc-blue_bg\">Présence de </span><span><span class=\"nc-blue_bg\">craving</span></span> (= <span>facteur de risque de rechute</span>)</td></tr>\n        </tbody>\n      </table>\n      <p>Le <strong><span class=\"nc-blue_bg\">test de Fagerström</span></strong> existe en version complète (6 questions, <span>score</span> <span>0-10</span>) et en <strong>version simplifiée</strong> (2 questions — <span>les</span> plus discriminantes) :</p>\n      <table>\n        <thead><tr><th>Question (version simplifiée)</th><th>Cotation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"nc-red nc-bold\">Nombre de c</span><span><span class=\"nc-red nc-bold\">iga</span></span><span class=\"nc-red nc-bold\">rettes / jour</span></td><td><span>≤ 10</span> → 0 ; 11-20 → 1 ; 21-30 → 2 ; ≥ 31 → 3</td></tr>\n          <tr><td>Délai entre le réveil et la 1ʳᵉ c<span>iga</span>rette</td><td><span>≤ 5 min</span> → 3 ; <span>6-30 min</span> → 2 ; <span>31-60 min</span> → 1 ; &gt; <span>60 min</span> → 0</td></tr>\n        </tbody>\n      </table>\n      <p>Interprétation (version simplifiée) : <span>0-1</span> non dépendant · <span>2-3</span> dépendance modérée · <span>4-6</span> dépendance forte.</p>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Chez un patient <strong>dépendant</strong>, un <span class=\"nc-pink_bg\">traitement</span> <span><span class=\"nc-pink_bg nc-bold\">médicamenteux</span></span> est recommandé pour l'aide à l'arrêt.\n      </div><div class=\"callout\"><p>Le score simplifié à 0–1 indique une <span class=\"nc-purple_bg\">dépendance</span> physique faible ou non détectée par ce test, sans exclure une <span class=\"nc-purple_bg\">dépendance</span> psychologique ou un <span class=\"nc-red nc-bold\">trouble</span> de l’usage.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":3},{"id":"75-21","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes de sevrage en tabac","contenu":"<div class=\"notion-course\"><p>Le <span>syndrome de sevrage</span> est consécutif au manque de <span>nicotine</span>. Il apparaît <strong>rapidement</strong> après un arrêt brutal ou une diminution significative de la quantité fumée, et constitue le <span><span class=\"nc-red nc-bold\">facteur de rechute principal</span></span>.</p>\n      <table>\n        <thead><tr><th>Domaine</th><th>Signes</th></tr></thead>\n        <tbody>\n          <tr><td>Humeur</td><td><span><span class=\"nc-orange_bg\">Humeur dépressive</span></span> ; irritabilité ; frustration ; colère</td></tr>\n          <tr><td>Sommeil</td><td><span><span class=\"nc-orange_bg\">Insomnie</span></span></td></tr>\n          <tr><td>Cognitif</td><td><span><span class=\"nc-orange_bg\">Anxiété</span></span> ; <span class=\"nc-blue_bg\">difficultés de concentration</span></td></tr>\n          <tr><td>Appétit / poids</td><td><span class=\"nc-blue_bg\">Augmentation de l'appétit</span> ; <span><span class=\"nc-orange_bg\">prise de poids</span></span></td></tr>\n        </tbody>\n      </table></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"75-22","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les complications médicales non psychiatriques","contenu":"<div class=\"notion-course\"><h4>Complications à rechercher</h4><table><thead><tr><th>Domaine</th><th>Repères</th></tr></thead><tbody><tr><td>Cancers</td><td>Poumon, VADS, œsophage, <span class=\"nc-red\">estomac</span>, <span class=\"nc-red\">foie</span>, <span class=\"nc-red\">pancréas</span>, colorectal, rein, <span class=\"nc-red\">vessie</span>, col utérin et leucémie myéloïde ; risque variable selon localisation et histologie.</td></tr><tr><td>Cardiovasculaire</td><td>Infarctus, AVC, AOMI, anévrisme ; maladie de Buerger dans le cadre vasculaire.</td></tr><tr><td>Respiratoire</td><td><span class=\"nc-orange_bg\">BPCO</span>, <span class=\"nc-orange_bg\">emphysème</span>, <span class=\"nc-orange_bg\">bronchite chronique</span>, exacerbations d’<span class=\"nc-orange_bg\">asthme</span> et <span class=\"nc-purple_bg\">infections</span>.</td></tr><tr><td>Reproduction/<span class=\"nc-green nc-bold\">grossesse</span></td><td>Baisse de fertilité, <span class=\"nc-orange_bg\">GEU</span>, fausse couche, complications placentaires, prématurité, retard de croissance et mort fœtale.</td></tr><tr><td>Autres</td><td>Parodontopathies, mauvaise cicatrisation, vieillissement cutané ; <span class=\"nc-blue_bg\">polyglobulie</span> possible.</td></tr></tbody></table><div class=\"callout\"><p>Ne pas mémoriser des listes de cancers « jamais liés au tabac » ni présenter le tabac comme protecteur d’Alzheimer. Les associations inverses décrites pour certaines maladies ne constituent jamais une indication à fumer.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"75-23","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître le diagnostic des comorbidités psychiatriques et addictives","contenu":"<div class=\"notion-course\"><h4>Comorbidités et interactions</h4><ul><li>Rechercher <span class=\"nc-orange_bg\">anxiété</span>, <span class=\"nc-red_bg\">dépression</span>, risque suicidaire, psychose et <span class=\"nc-red nc-bold\">trouble</span> bipolaire selon le contexte. Un <span class=\"nc-red nc-bold\">trouble</span> stabilisé ne contre-indique pas l’aide à l’arrêt.</li><li>Évaluer <span class=\"nc-red_bg\">alcool</span>, <span class=\"nc-red_bg\">cannabis</span> et autres substances ; le <span class=\"nc-red_bg\">cannabis</span> rend l’arrêt plus difficile mais ne le rend pas impossible.</li><li>Tenir compte de <span class=\"nc-green nc-bold\">grossesse</span>, maladie cardiovasculaire, BPCO, fragilité sociale et antécédents de tentatives.</li><li>L’arrêt de la fumée lève l’induction enzymatique : risque d’augmentation des concentrations de clozapine/olanzapine notamment. Anticiper surveillance et adaptation avec le prescripteur ; la nicotine n’explique pas cette interaction.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"75-24","rang":"A","rubrique":"Prise en charge","titre":"Moment du sevrage : connaître la proposition d'aide à l'arrêt à chaque contact avec un professionnel de santé","contenu":"<div class=\"notion-course\"><h4>Proposer l’arrêt à <span class=\"nc-yellow_bg nc-bold\">chaque</span> contact</h4><table><thead><tr><th>5 A</th><th>Action</th></tr></thead><tbody><tr><td>Ask</td><td>Repérer le tabagisme.</td></tr><tr><td><span class=\"nc-red nc-bold\">Advise</span></td><td>Conseiller clairement l’arrêt, de façon personnalisée et respectueuse.</td></tr><tr><td><span class=\"nc-red nc-bold\">Assess</span></td><td>Évaluer dépendance et disposition au changement.</td></tr><tr><td><span class=\"nc-red nc-bold\">Assist</span></td><td>Proposer aides, <span class=\"nc-pink_bg\">traitement</span> et stratégies.</td></tr><tr><td><span class=\"nc-red nc-bold\">Arrange</span></td><td>Organiser le suivi, pas seulement remettre une brochure.</td></tr></tbody></table><p><span class=\"nc-green nc-bold\">Grossesse</span>, maladie liée au tabac et chirurgie sont des occasions prioritaires. Un arrêt plusieurs semaines avant une intervention est préférable ; même tardif, l’arrêt doit être encouragé sans culpabilisation.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_1718021/fr/\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Arrêt du tabac : recommandations et algorithmes</a></li></ul><p></p></details>","frequence":1},{"id":"75-25","rang":"A","rubrique":"Prise en charge","titre":"Connaître les moyens de prévention primaire et secondaire","contenu":"<div class=\"notion-course\"><h4>Prévenir l’entrée et aider à sortir du tabagisme</h4><ul><li>Prix et fiscalité, limitation de la publicité et de l’accès aux mineurs, <span class=\"nc-yellow_bg\">paquet neutre</span> et avertissements, protection contre le tabagisme passif.</li><li>Repères historiques : lois <span class=\"nc-blue\">Veil</span> et <span class=\"nc-blue\">Évin</span>, décret de 2006 ; programme actuel 2023–2027 et objectif génération sans tabac en 2032.</li><li>Espaces sans tabac étendus en 2025, notamment parcs, plages et abords de certains lieux accueillant des enfants.</li><li>Prévention secondaire : repérage systématique, conseil, accès aux traitements et soutien, ciblage des inégalités sociales.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://sante.gouv.fr/IMG/pdf/plan_national_contre_le_tabac.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère de la Santé · Programme national de lutte contre le tabac 2023–2027</a></li><li><a href=\"https://www.info.gouv.fr/actualite/interdiction-de-fumer-de-nouveaux-lieux-concernes-cet-ete\" target=\"_blank\" rel=\"noopener noreferrer\">Gouvernement · Extension des espaces sans tabac en 2025</a></li></ul><p></p></details>","frequence":0},{"id":"75-26","rang":"A","rubrique":"Prise en charge","titre":"Connaître les traitements de la dépendance au tabac (pharmacologiques et non pharmacologiques)","contenu":"<div class=\"notion-course\"><h4><span class=\"nc-pink_bg\">Traitement</span> associé à l’accompagnement</h4><ul><li>Conseil, <span class=\"nc-green_bg\">entretien motivationnel</span>, soutien, stratégies comportementales/TCC, <span class=\"nc-pink nc-bold\">Tabac info service</span> ou <span class=\"nc-yellow_bg\">consultation</span> spécialisée selon besoin.</li><li>Première intention médicamenteuse : <span class=\"nc-pink\">substituts nicotiniques</span>, souvent patch pour le fond + forme orale rapide pour les envies.</li><li>Adapter la dose à la <span class=\"nc-purple_bg\">dépendance</span>, aux consommations et aux symptômes : <span class=\"nc-blue_bg nc-bold\">craving</span>/manque → rechercher sous-dosage ; <span class=\"nc-blue_bg\">nausées</span>, <span class=\"nc-yellow_bg\">palpitations</span> ou <span class=\"nc-yellow_bg\">céphalées</span> → évaluer surdosage et autres causes.</li><li>Le repère « une cigarette ≈ <span class=\"nc-pink_bg nc-bold\">1 mg</span> » est une approximation de départ, pas une conversion exacte. <span class=\"nc-pink_bg\">Traitement</span> souvent sur plusieurs mois, durée individualisée.</li><li>Effets indésirables : irritation cutanée ou buccale, troubles <span class=\"nc-blue_bg\">digestifs</span>, <span class=\"nc-yellow_bg\">céphalées</span> ; vérifier le RCP. <span class=\"nc-green nc-bold\">Grossesse</span> et maladie cardiovasculaire nécessitent une adaptation, mais continuer à fumer est plus dangereux.</li><li><span class=\"nc-pink\">Varénicline</span> ou <span class=\"nc-pink_bg\">bupropion</span> après évaluation des contre-indications en cas d’échec/intolérance ; le vapotage n’est pas une substitution médicamenteuse.</li><li>Remboursement : produits inscrits à 65 % sur prescription, sans forfait annuel ; exceptions selon spécialité et couverture.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_1718021/fr/\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Arrêt du tabac : recommandations et algorithmes</a></li><li><a href=\"https://www.ameli.fr/assure/remboursements/rembourse/medicaments-vaccins-dispositifs-medicaux/prise-charge-substituts-nicotiniques\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · Prise en charge des substituts nicotiniques</a></li></ul><p></p></details>","frequence":4},{"id":"75-27","rang":"A","rubrique":"Prise en charge","titre":"Connaître les outils institutionnels (tabac info service)","contenu":"<div class=\"notion-course\"><h4>Un accompagnement accessible</h4><ul><li><span class=\"nc-pink nc-bold\">Tabac info service</span> : site, application et <span class=\"nc-green_bg\">accompagnement téléphonique</span> au 39 89.</li><li>Médecin traitant, pharmacien et autres professionnels, <span class=\"nc-blue_bg\">consultation de tabacologie</span> ou CSAPA selon situation.</li><li>Le forfait annuel de 150 € est supprimé : remboursement des substituts inscrits sans plafond annuel, sur prescription.</li><li>En cas de précarité ou d’échecs répétés, rechercher les obstacles matériels et coordonner les aides.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://www.ameli.fr/assure/remboursements/rembourse/medicaments-vaccins-dispositifs-medicaux/prise-charge-substituts-nicotiniques\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · Prise en charge des substituts nicotiniques</a></li></ul><p></p></details>","frequence":1},{"id":"75-28","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de la prise en charge après un évènement aigu : infarctus du myocarde, décompensation respiratoire…","contenu":"<div class=\"notion-course\"><h4>Après un événement aigu</h4><ol><li>Traiter l’événement et repérer immédiatement tabagisme, manque, dépendance et motivation.</li><li>Proposer l’arrêt dès l’hospitalisation avec accompagnement et substitution nicotinique adaptée, y compris en contexte cardiovasculaire sous surveillance.</li><li>À la sortie : ordonnance, conseils pratiques, rendez-vous et transmission au médecin traitant/tabacologue.</li><li>Prévenir la reprise liée au stress, à l’entourage ou au retour à domicile ; réévaluer doses et autres médicaments.</li></ol><div class=\"callout\"><p>L’hospitalisation seule n’assure pas un arrêt durable. Ne pas annoncer un retour certain au risque cardiovasculaire d’un <span class=\"nc-red nc-bold\">non-fumeur</span> après trois ans.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"75-29","rang":"B","rubrique":"Prise en charge","titre":"Savoir rechercher des comorbidités en fonction du terrain","contenu":"<div class=\"notion-course\"><h4>Adapter au terrain</h4><ul><li>Rechercher <span class=\"nc-orange_bg\">anxiété</span>, <span class=\"nc-red_bg\">dépression</span>, risque suicidaire, psychose et <span class=\"nc-red nc-bold\">trouble</span> bipolaire selon le contexte. Un <span class=\"nc-red nc-bold\">trouble</span> stabilisé ne contre-indique pas l’aide à l’arrêt.</li><li>Évaluer <span class=\"nc-red_bg\">alcool</span>, <span class=\"nc-red_bg\">cannabis</span> et autres substances ; le <span class=\"nc-red_bg\">cannabis</span> rend l’arrêt plus difficile mais ne le rend pas impossible.</li><li>Tenir compte de <span class=\"nc-green nc-bold\">grossesse</span>, maladie cardiovasculaire, BPCO, fragilité sociale et antécédents de tentatives.</li><li>L’arrêt de la fumée lève l’induction enzymatique : risque d’augmentation des concentrations de clozapine/olanzapine notamment. Anticiper surveillance et adaptation avec le prescripteur ; la nicotine n’explique pas cette interaction.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"75-30","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de la prise en charge à long terme : savoir que les rechutes sont la règle d'où la proposition systématique de l'arrêt du tabac","contenu":"<div class=\"notion-course\"><h4>Le suivi fait partie du <span class=\"nc-pink_bg\">traitement</span></h4><ul><li>Consultations rapprochées au début puis espacées selon stabilité ; suivi prolongé, souvent au moins <span class=\"nc-pink nc-bold\">6–12 mois</span>.</li><li>Évaluer abstinence, envies, humeur, sommeil, poids, autres consommations et effets du <span class=\"nc-pink_bg\">traitement</span>.</li><li>Reprise : analyser les déclencheurs, corriger le sous-dosage éventuel et proposer une nouvelle tentative sans blâme.</li><li>Les reprises sont fréquentes mais ni obligatoires ni une faute. Aucun nombre fixe de tentatives ne prédit le succès individuel ; <span class=\"nc-yellow_bg nc-bold\">chaque</span> période sans fumée a un intérêt.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":1},{"id":"75-31","rang":"B","rubrique":"Prise en charge","titre":"Connaître l’aide médicamenteuse autre que traitements substitutifs nicotiniques","contenu":"<div class=\"notion-course\"><h4>Aides non nicotiniques</h4><table><thead><tr><th>Molécule</th><th>Principes et vigilance</th></tr></thead><tbody><tr><td><span class=\"nc-pink\">Varénicline</span></td><td>Agoniste partiel nicotinique : réduit manque et récompense. <span class=\"nc-blue_bg\">Nausées</span>, rêves anormaux, <span class=\"nc-orange_bg\">insomnie</span> ; adaptation rénale. Surveiller l’état psychique sans présenter un risque suicidaire causal comme systématiquement démontré.</td></tr><tr><td><span class=\"nc-pink_bg\">Bupropion</span></td><td>Action noradrénergique/dopaminergique. Risque convulsif : contre-indiqué notamment si épilepsie, anorexie/boulimie, sevrage brutal <span class=\"nc-red_bg\">alcool</span>/BZD ; vérifier aussi <span class=\"nc-red nc-bold\">trouble</span> bipolaire, interactions et RCP. <span class=\"nc-orange_bg\">Insomnie</span> et hypertension possibles.</td></tr></tbody></table><p>Choix après échec ou intolérance des substituts et accompagnement adapté, avec vérification de l’indication, des contre-indications <span class=\"nc-blue_bg\">et de la</span> disponibilité. <span class=\"nc-green nc-bold\">Grossesse</span> : ne pas prescrire ces traitements comme des alternatives banales aux substituts.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"75-32","rang":"B","rubrique":"Prise en charge","titre":"Savoir quand adresser un patient en consultation de tabacologie","contenu":"<div class=\"notion-course\"><p>La <strong><span class=\"nc-blue_bg\">consultation de tabacologie</span></strong> s'adresse aux personnes ayant des <span>difficultés à arrêter</span> de consommer du <span>tabac</span>. Sont notamment concernés :</p>\n      <ul>\n        <li><span>Échecs répétés</span> des tentatives d'arrêt.</li>\n        <li><span>Dépendance forte</span> à la nicotine (<span>score</span> de <span class=\"nc-blue_bg nc-bold\">Fagerström</span> élevé).</li>\n        <li><span>Comorbidités psychiatriques</span> ou <span>addictives</span> associées.</li>\n        <li><span>Terrain</span> à risque ou demande spécifique du patient.</li>\n      </ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Addiction au tabac (75)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0}],"astuces":[{"type":"piege","titre":"Actualisation","contenu":"<div class=\"notion-course\"><p>Le forfait de 150 € est supprimé ; remboursement des produits inscrits sans plafond annuel.</p></div>"},{"type":"piege","titre":"Suivi","contenu":"<div class=\"notion-course\"><p>Une reprise appelle une adaptation, pas une culpabilisation.</p></div>"}],"strategie":{"Démarche diagnostique":"<div class=\"notion-course\"><ul><li>Repérer toutes les consommations et évaluer dépendance, comorbidités et motivation.</li></ul></div>","Prise en charge":"<div class=\"notion-course\"><ul><li>Accompagnement + substituts adaptés ; anticiper suivi et interactions avec les médicaments.</li></ul></div>","Examens complémentaires":"<div class=\"notion-course\"><ul><li>Bilan orienté par symptômes et facteurs de risque ; ne pas attendre une complication pour proposer l’arrêt.</li></ul></div>"},"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Consommation actuelle et exposition passive ?","detail":"<ul><li>Interroger sans jugement sur tous les produits, modes, quantités et entourage.</li><li>Présenter les bénéfices de l’arrêt et les risques de la combustion.</li></ul>","branches":[{"label":"Fumeur actuel","to":"evaluer"},{"label":"Non-fumeur / ancien fumeur","to":"prevenir"}]},{"id":"prevenir","kind":"finish","label":"Prévenir exposition et reprise","detail":"<ul><li>Environnement sans fumée, jeunes et situations à risque.</li><li>Une cigarette électronique produit un aérosol ; elle n’est pas inoffensive.</li></ul>","branches":[]},{"id":"evaluer","kind":"decision","label":"Dépendance, comorbidités et tentatives antérieures","detail":"<ul><li>Délai première cigarette, manque, automatismes, contexte émotionnel et traitements.</li><li>Rechercher consommations associées et symptômes psychiatriques.</li></ul>","branches":[{"label":"Prêt à essayer l’arrêt","to":"traiter"},{"label":"Ambivalent / pas prêt","to":"motiver"}]},{"id":"motiver","kind":"finish","label":"Entretien motivationnel et nouvelle proposition","detail":"<ul><li>Explorer avantages/inconvénients et proposer une réduction accompagnée vers l’arrêt.</li><li>Respecter le rythme, fixer un prochain contact.</li></ul>","branches":[]},{"id":"traiter","kind":"decision","label":"Accompagnement et substituts adaptés","detail":"<ul><li>Associer si besoin forme transdermique et forme rapide ; ajuster au manque.</li><li>Alternatives non nicotiniques selon indication, contre-indications et disponibilité.</li></ul>","branches":[{"label":"Suivi et ajustement","to":"suivi"}]},{"id":"suivi","kind":"decision","label":"Manque, effets indésirables ou reprise ?","detail":"<ul><li>Adapter le traitement et identifier les déclencheurs sans culpabiliser.</li><li>Planifier suivi, soutien et Tabac info service ; une reprise permet d’ajuster le projet.</li></ul>","branches":[{"label":"Difficultés persistantes / situation complexe","to":"expert"},{"label":"Objectifs atteints","to":"maintien"}]},{"id":"expert","kind":"finish","label":"Avis de tabacologie/addictologie","detail":"<ul><li>Dépendance importante, échecs répétés, grossesse ou comorbidités complexes.</li></ul>","branches":[]},{"id":"maintien","kind":"finish","label":"Consolider l’arrêt et la prévention des reprises","detail":"<ul><li>Réévaluer le traitement et l’exposition de l’entourage.</li></ul>","branches":[]}]},"cards":[{"i":"1aadca5bc4a9","n":75,"o":"75-1","u":"Définition","t":"Connaître les principaux risques liés au tabagisme actif, au tabagisme passif, et au tabagisme in utero","q":"Quels sont les principaux risques liés au tabagisme passif chez l'adulte et la femme enceinte ?","a":"<div class=\"notion-course\"><p>Les principaux risques liés au tabagisme passif sont :</p><ul><li>Chez l'adulte : <strong><span class=\"nc-red_bg\">cancer pulmonaire</span></strong> (risque relatif +25%), <strong>décès cardiovasculaire</strong> (risque relatif +20-30%). Le risque est présent même à faibles doses.</li><li>Chez la <span class=\"nc-red nc-bold\">femme enceinte</span> : <strong>retard de croissance intra-utérin (<span class=\"nc-red_bg\">RCIU</span>)</strong>, <strong><span class=\"nc-red_bg\">accouchement prématuré</span></strong>.</li></ul></div>"},{"i":"31e4a669e37b","n":75,"o":"75-1","u":"Définition","t":"Connaître les principaux risques liés au tabagisme actif, au tabagisme passif, et au tabagisme in utero","q":"Quels sont les principaux risques liés au tabagisme actif pour le fumeur ?","a":"<div class=\"notion-course\"><p>Les principaux risques liés au tabagisme actif incluent :</p><ul><li><strong>Cancers</strong> : poumon, voies aéro-digestives supérieures, <span class=\"nc-red\">vessie</span>, <span class=\"nc-red\">pancréas</span>.</li><li><strong>Pathologies cardiovasculaires</strong> : Hypertension artérielle (<span class=\"nc-orange_bg\">HTA</span>), infarctus du myocarde (<span class=\"nc-orange_bg\">IDM</span>), artériopathie oblitérante des membres inférieurs (AOMI), accidents vasculaires cérébraux (<span class=\"nc-orange_bg\">AVC</span>).</li><li><strong>Pathologies respiratoires</strong> : Bronchopneumopathie chronique obstructive (<span class=\"nc-orange_bg\">BPCO</span>), <span class=\"nc-orange_bg\">emphysème</span>.</li><li><strong>Troubles de la reproduction</strong> : baisse de la fertilité, troubles de la <span class=\"nc-green nc-bold\">grossesse</span>.</li></ul></div>"},{"i":"5027edce21aa","n":75,"o":"75-1","u":"Définition","t":"Connaître les principaux risques liés au tabagisme actif, au tabagisme passif, et au tabagisme in utero","q":"Quelle est la particularité de la toxicité du courant secondaire de la fumée de cigarette par rapport au courant primaire ?","a":"<div class=\"notion-course\"><p>Le <strong>courant secondaire</strong> (fumée s'échappant du bout incandescent de la cigarette) est <strong>plus toxique</strong> que le courant primaire <span class=\"nc-red_bg\">inhalé par le fumeur</span>. Il est <strong>plus concentré en <span class=\"nc-yellow_bg\">monoxyde de carbone</span>, goudrons et cancérigènes</strong>, et n'est pas filtré.</p></div>"},{"i":"ce1c7adcd14c","n":75,"o":"75-1","u":"Définition","t":"Connaître les principaux risques liés au tabagisme actif, au tabagisme passif, et au tabagisme in utero","q":"Quels sont les principaux risques du tabagisme passif pour l'enfant et le nourrisson et du tabagisme in utero pour le fœtus ou la grossesse ?","a":"<div class=\"notion-course\"><p>Les principaux risques incluent :</p><ul><li>Pour l'enfant / nourrisson (tabagisme passif) : <strong>otites et <span class=\"nc-purple_bg\">infections</span> <span class=\"nc-purple_bg nc-bold\">ORL</span></strong>, <strong><span class=\"nc-purple_bg\">infections</span> <span class=\"nc-purple_bg nc-bold\">pulmonaires</span></strong>, <strong><span class=\"nc-orange_bg\">asthme</span></strong>, <strong><span class=\"nc-red nc-bold\">mort subite du nourrisson</span></strong>.</li><li>Pour le fœtus ou la <span class=\"nc-green nc-bold\">grossesse</span> (tabagisme in utero) : <strong>fausse couche</strong>, <strong>mort fœtale in utero</strong>, <strong><span class=\"nc-red_bg\">rupture prématurée des membranes</span></strong>, <strong><span class=\"nc-red_bg\">accouchement prématuré</span></strong>, <strong>retard de croissance intra-utérin (<span class=\"nc-red_bg\">RCIU</span>)</strong>, <strong><span class=\"nc-green nc-bold\">grossesse</span> extra-utérine</strong>, <strong><span class=\"nc-orange_bg\">placenta praevia</span></strong>, <strong><span class=\"nc-orange_bg\">hématome rétroplacentaire</span></strong>.</li></ul></div>"},{"i":"1dd0bca7cd6d","n":75,"o":"75-10","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme chez la femme enceinte","q":"Quelles sont les caractéristiques sociodémographiques des femmes enceintes plus susceptibles de poursuivre leur tabagisme durant la grossesse ?","a":"<div class=\"notion-course\"><p>La poursuite du tabagisme est plus fréquente chez les femmes enceintes <strong>les plus jeunes</strong> et <strong>les <span class=\"nc-red nc-bold\">moins diplômées</span></strong>.</p></div>"},{"i":"2df79b70d2f5","n":75,"o":"75-10","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme chez la femme enceinte","q":"Quelle est la proportion de femmes enceintes qui continuent de fumer pendant leur grossesse ?","a":"<div class=\"notion-course\"><p>Le « 50 % » du cours concerne les fumeuses avant <span class=\"nc-green nc-bold\">grossesse</span>. Enquête 2016 : 16,2 % de toutes les femmes fumaient au troisième trimestre ; 45,8 % des fumeuses avaient arrêté.</p></div>"},{"i":"4c29f2ab0cb9","n":75,"o":"75-11","u":"Epidémiologie","t":"Connaître les modes de consommation du tabac","q":"Quels produits du tabac sont utilisés par voie buccale ?","a":"<div class=\"notion-course\"><p>Snus et tabac à chiquer : absorption par la muqueuse. Le snus est interdit à la commercialisation dans l’Union européenne sauf exception suédoise ; ne pas le confondre avec les sachets sans tabac.</p></div>"},{"i":"61d00ca6c5e2","n":75,"o":"75-11","u":"Epidémiologie","t":"Connaître les modes de consommation du tabac","q":"Quels sont les principaux modes de consommation du tabac entraînant une inhalation après combustion complète ?","a":"<div class=\"notion-course\"><p>Les produits du tabac consommés par inhalation après combustion complète à haute température sont :</p><ul><li>La <strong>chicha</strong> (pipe à eau).</li><li>Les <strong>cigarettes</strong> manufacturées et roulées.</li><li>Les <strong>cigarillos</strong> et <strong>cigares</strong>.</li><li>La <strong>pipe</strong>.</li></ul></div>"},{"i":"9cb4297480bf","n":75,"o":"75-11","u":"Epidémiologie","t":"Connaître les modes de consommation du tabac","q":"Comment doit-on considérer les produits de tabac chauffé par rapport aux autres modes de consommation du tabac ?","a":"<div class=\"notion-course\"><p>Tabac chauffé : aérosol issu de tabac, nicotine et substances toxiques ; ne pas le confondre avec le vapotage ni considérer le produit sans risque.</p></div>"},{"i":"fe08ce719467","n":75,"o":"75-11","u":"Epidémiologie","t":"Connaître les modes de consommation du tabac","q":"Quels produits distinguer parmi les usages sans combustion ?","a":"<div class=\"notion-course\"><p>Vapotage d’un e-liquide, tabac à priser par voie nasale, tabac buccal. Les risques et voies d’absorption diffèrent.</p></div>"},{"i":"1107aebf39b6","n":75,"o":"75-12","u":"Epidémiologie","t":"Connaître l’ordre de grandeur du nombre de cas de cancer liés au tabac","q":"Quel est le nombre annuel de décès spécifiquement par cancer du poumon liés au tabac en France ?","a":"<div class=\"notion-course\"><p>Sur les décès par <span class=\"nc-green_bg\">cancer</span> liés au tabac, environ <strong>32 000</strong> sont des cancers du poumon.</p><p>Repère historique de l’estimation 2015, non chiffre actuel.</p></div>"},{"i":"281a47584686","n":75,"o":"75-12","u":"Epidémiologie","t":"Connaître l’ordre de grandeur du nombre de cas de cancer liés au tabac","q":"Existe-t-il un seuil de consommation de tabac sans risque en termes de risque de cancer ?","a":"<div class=\"notion-course\"><p>Non, il n'existe <strong><span class=\"nc-red_bg\">pas de seuil de consommation sans risque</span></strong>. Même le tabagisme passif augmente le risque de <span class=\"nc-green_bg\">cancer</span>.</p></div>"},{"i":"5c819d8cfdc2","n":75,"o":"75-12","u":"Epidémiologie","t":"Connaître l’ordre de grandeur du nombre de cas de cancer liés au tabac","q":"Quel est le nombre annuel de décès par cancer liés au tabac en France ?","a":"<div class=\"notion-course\"><p>Le tabac est responsable d'environ <strong>46 000 à 46 500</strong> décès par <span class=\"nc-green_bg\">cancer</span> par an en France.</p><p>Repère historique de l’estimation 2015, non chiffre actuel.</p></div>"},{"i":"c0115d2f6b53","n":75,"o":"75-12","u":"Epidémiologie","t":"Connaître l’ordre de grandeur du nombre de cas de cancer liés au tabac","q":"Quelle est la part des cancers attribuables au tabac au global en France ?","a":"<div class=\"notion-course\"><p>Environ un cinquième des nouveaux cancers en France ; premier facteur évitable. Ne pas confondre nouveaux cas et décès.</p></div>"},{"i":"2475ceeacb38","n":75,"o":"75-13","u":"Epidémiologie","t":"Connaître la part du tabac dans la mortalité en France","q":"Quelle est la part du tabac dans les décès chez l'homme en France ?","a":"<div class=\"notion-course\"><p>La part du tabac dans l'ensemble des décès chez l'homme en France est de <strong>20 %</strong>.</p><p>Repère historique de l’estimation 2015, non chiffre actuel.</p></div>"},{"i":"41af9936e874","n":75,"o":"75-13","u":"Epidémiologie","t":"Connaître la part du tabac dans la mortalité en France","q":"Quelle est la part du tabac dans les décès chez la femme en France ?","a":"<div class=\"notion-course\"><p>La part du tabac dans l'ensemble des décès chez la femme en France est de <strong>7 %</strong>.</p><p>Repère historique de l’estimation 2015, non chiffre actuel.</p></div>"},{"i":"545dd40f70c2","n":75,"o":"75-13","u":"Epidémiologie","t":"Connaître la part du tabac dans la mortalité en France","q":"Quel est le nombre estimé de décès prématurés attribuables au tabac chaque année en France ?","a":"<div class=\"notion-course\"><p>Estimation actualisée : environ 68 000 décès attribuables en 2023. Le chiffre 75 000 correspond à l’estimation pour 2015.</p></div>"},{"i":"6842163832ac","n":75,"o":"75-13","u":"Epidémiologie","t":"Connaître la part du tabac dans la mortalité en France","q":"Quel est le statut du tabac en matière de mortalité en France ?","a":"<div class=\"notion-course\"><p>Le tabac est la <strong>première cause de décès évitable</strong> en France.</p></div>"},{"i":"424584df5bc6","n":75,"o":"75-14","u":"Epidémiologie","t":"Connaître la mortalité liée au tabagisme actif","q":"Quelle est la proportion de fumeurs qui mourront prématurément d'une maladie liée au tabac ?","a":"<div class=\"notion-course\"><p>Environ <strong>un fumeur sur deux</strong> (soit <strong>50 %</strong>) mourra prématurément d'une maladie due au tabac.</p></div>"},{"i":"815c3473ad24","n":75,"o":"75-14","u":"Epidémiologie","t":"Connaître la mortalité liée au tabagisme actif","q":"Quelle cause spécifique de cancer est la plus fortement associée au tabagisme actif en termes de mortalité annuelle, et combien de décès lui sont attribués ?","a":"<div class=\"notion-course\"><p>La cause spécifique de <span class=\"nc-green_bg\">cancer</span> la plus fortement associée au tabagisme actif est le <strong><span class=\"nc-green_bg\">cancer du</span> poumon</strong>, responsable d'environ <strong>32 000</strong> décès par an.</p><p>Repère historique de l’estimation 2015, non chiffre actuel.</p></div>"},{"i":"e94f9ca10801","n":75,"o":"75-14","u":"Epidémiologie","t":"Connaître la mortalité liée au tabagisme actif","q":"Quelles sont les trois principales causes de décès prématuré liées au tabagisme actif, et leur mortalité annuelle respective en France selon les données de 2015 ?","a":"<div class=\"notion-course\"><ul><li><strong>Cancers</strong> : environ <strong>46 000</strong> décès par an.</li><li><strong>Maladies cardiovasculaires</strong> : environ <strong>17 000</strong> décès par an.</li><li><strong>Maladies respiratoires chroniques</strong> : environ <strong>12 000</strong> décès par an.</li></ul></div>"},{"i":"3a119b43ca76","n":75,"o":"75-15","u":"Epidémiologie","t":"Connaître l’impact sur la mortalité cardiovasculaire","q":"Quel est l'impact général du tabac sur le risque de développer une maladie cardiovasculaire ?","a":"<div class=\"notion-course\"><p>Risque accru d’infarctus, AVC et artériopathie, même à faible dose ; pas de multiplication universelle par 20.</p></div>"},{"i":"844861eb8ad2","n":75,"o":"75-15","u":"Epidémiologie","t":"Connaître l’impact sur la mortalité cardiovasculaire","q":"Le tabac est-il un facteur de risque pour d'autres pathologies cardiovasculaires que l'IDM et l'AOMI ?","a":"<div class=\"notion-course\"><p>Oui, le tabac est également un facteur de risque pour :</p><ul><li>L'<strong>AVC</strong> (accident vasculaire cérébral), avec un RR ≈ 1,5-2.</li><li>L'<strong>anévrisme de l'aorte abdominale</strong>.</li><li>L'<strong><span class=\"nc-orange_bg\">HTA</span></strong> (hypertension artérielle) et la <strong><span class=\"nc-orange_bg\">cardiopathie hypertensive</span></strong>.</li></ul></div>"},{"i":"9ab96c93f2b9","n":75,"o":"75-15","u":"Epidémiologie","t":"Connaître l’impact sur la mortalité cardiovasculaire","q":"Quel est l'impact du tabac sur le risque d'infarctus du myocarde et d'artériopathie oblitérante des membres inférieurs (AOMI) ?","a":"<div class=\"notion-course\"><p>Le tabac augmente le risque :</p><ul><li>D'<strong>infarctus du myocarde (<span class=\"nc-orange_bg\">IDM</span>)</strong> avec un RR ≈ 3. Il est le <strong>2<sup>e</sup> facteur de risque d'<span class=\"nc-orange_bg\">IDM</span></strong> après la dyslipidémie, avec un <strong>effet-dose et sans dose-seuil</strong>.</li><li>D'<strong>artériopathie oblitérante des membres inférieurs (AOMI)</strong> avec un RR ≈ 2-7, et <strong>90 % des patients atteints d'AOMI sont fumeurs</strong>.</li></ul></div>"},{"i":"cebd7b303a23","n":75,"o":"75-15","u":"Epidémiologie","t":"Connaître l’impact sur la mortalité cardiovasculaire","q":"Le tabac est-il un facteur de risque cardiovasculaire évitable et touche-t-il spécifiquement certaines populations ?","a":"<div class=\"notion-course\"><p>Oui, le tabac est la <strong>1<sup>re</sup> cause de maladie cardiovasculaire évitable</strong>. Il est notamment le <strong>1<sup>er</sup> facteur de risque cardiovasculaire de la femme non ménopausée</strong>. L'effet est plus marqué chez les <strong>femmes</strong>, les <strong>hommes jeunes</strong> et les <strong>grands fumeurs</strong>.</p></div>"},{"i":"d5821dc1884b","n":75,"o":"75-15","u":"Epidémiologie","t":"Connaître l’impact sur la mortalité cardiovasculaire","q":"Quel est le risque de complications cardiovasculaires associé à l'association tabac et contraception œstroprogestative ?","a":"<div class=\"notion-course\"><p>L'association tabac et contraception œstroprogestative <strong>majore le risque thromboembolique</strong>.</p></div>"},{"i":"56a7a3b7e530","n":75,"o":"75-16","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme et celles des principales maladies liées au tabac","q":"Quel est le poids attribuable du tabac pour les cancers et les maladies cardiovasculaires en France ?","a":"<div class=\"notion-course\"><p>Premier facteur évitable de <span class=\"nc-green_bg\">cancer</span>, environ un cinquième des nouveaux cas. Risque cardiovasculaire fortement accru, variable selon maladie et exposition : pas de coefficient unique ×20.</p></div>"},{"i":"74a56687d009","n":75,"o":"75-16","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme et celles des principales maladies liées au tabac","q":"Quelles sont les trois grandes familles de maladies attribuables au tabagisme en France ?","a":"<div class=\"notion-course\"><ul><li>Les <strong>cancers</strong></li><li>Les <strong>maladies cardiovasculaires</strong></li><li>Les <strong>maladies respiratoires</strong></li></ul></div>"},{"i":"c684eabbd68c","n":75,"o":"75-16","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme et celles des principales maladies liées au tabac","q":"Comment peut-on décrire la prévalence du tabagisme en France chez les adultes de 18 à 75 ans ?","a":"<div class=\"notion-course\"><p>En 2024, 18–75 ans en France hexagonale : 25,0 % fument, 18,2 % quotidiennement. Dater et préciser la population.</p></div>"},{"i":"c93e06b05da9","n":75,"o":"75-16","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme et celles des principales maladies liées au tabac","q":"Quelles sont les principales maladies respiratoires liées au tabagisme ?","a":"<div class=\"notion-course\"><ul><li>La <strong>BPCO</strong> (bronchopneumopathie chronique obstructive)</li><li>L'<strong><span class=\"nc-orange_bg\">emphysème</span></strong></li><li>La <strong><span class=\"nc-orange_bg\">bronchite chronique</span></strong></li><li>L'<strong>aggravation de l'<span class=\"nc-orange_bg\">asthme</span></strong></li></ul></div>"},{"i":"36a306d61cc6","n":75,"o":"75-17","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme passif, les grandes notions de sur-risque","q":"Quel est le sur-risque de décès cardiovasculaire chez un adulte exposé au tabagisme passif ?","a":"<div class=\"notion-course\"><p>Le risque de <strong>décès cardiovasculaire</strong> est augmenté d'environ <strong>20 à 30 %</strong> chez l'adulte exposé au tabagisme passif.</p></div>"},{"i":"3d31b66fdc86","n":75,"o":"75-17","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme passif, les grandes notions de sur-risque","q":"Quel est le sur-risque de cancer pulmonaire chez un adulte exposé au tabagisme passif ?","a":"<div class=\"notion-course\"><p>Le risque de <strong><span class=\"nc-red_bg\">cancer pulmonaire</span></strong> est augmenté d'environ <strong>25 %</strong> chez l'adulte exposé au tabagisme passif.</p></div>"},{"i":"d758b114b332","n":75,"o":"75-17","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme passif, les grandes notions de sur-risque","q":"Quelle est la particularité du tabagisme passif en termes de seuil de risque ?","a":"<div class=\"notion-course\"><p>Il n'existe <strong>pas de seuil sans risque</strong> pour le tabagisme passif : même à faibles doses, il augmente le risque de maladie.</p></div>"},{"i":"fcf8eea01cde","n":75,"o":"75-17","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme passif, les grandes notions de sur-risque","q":"Quels sont les principaux risques pour la santé de l'enfant ou du nourrisson exposés au tabagisme passif ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-purple_bg\">Infections</span> <strong>ORL</strong> (notamment les otites)</li><li><span class=\"nc-purple_bg\">Infections</span> <strong><span class=\"nc-purple_bg nc-bold\">pulmonaires</span></strong> (comme la <span class=\"nc-orange nc-bold\">bronchite</span>)</li><li><strong><span class=\"nc-orange_bg\">Asthme</span></strong></li><li><strong><span class=\"nc-red nc-bold\">Mort subite du nourrisson</span></strong></li></ul></div>"},{"i":"3d207d6ab8aa","n":75,"o":"75-19","u":"Diagnostic positif","t":"Savoir dépister la consommation de tabac","q":"Comment doit-on évaluer la quantité de tabac consommée et quelles sont les équivalences de certains produits par rapport aux cigarettes manufacturées ?","a":"<div class=\"notion-course\"><p>Cigarettes : paquets de 20/jour × années, période par période. Autres produits : quantité et fréquence propres ; pas de conversion universelle joint/chicha/cigarillo en cigarettes.</p></div>"},{"i":"58f3df51e462","n":75,"o":"75-19","u":"Diagnostic positif","t":"Savoir dépister la consommation de tabac","q":"Comment dépiste-t-on systématiquement la consommation de tabac chez un patient ?","a":"<div class=\"notion-course\"><p>Le dépistage systématique de la consommation de tabac chez tout patient repose sur une <strong>question simple</strong> : « Fumez-vous ? »</p></div>"},{"i":"6331b128bef4","n":75,"o":"75-19","u":"Diagnostic positif","t":"Savoir dépister la consommation de tabac","q":"Quel est le piège classique concernant le paquet-année dans l'évaluation du risque lié au tabagisme ?","a":"<div class=\"notion-course\"><p>Le paquet-année ne résume pas tout le risque : durée, intensité et temps depuis l’arrêt comptent. Les lois de puissance ne sont pas un calcul individuel universel.</p></div>"},{"i":"9630f5d7d166","n":75,"o":"75-19","u":"Diagnostic positif","t":"Savoir dépister la consommation de tabac","q":"Quels sont les paramètres à évaluer pour décrire la consommation de tabac d'un patient ?","a":"<div class=\"notion-course\"><p>Pour caractériser la consommation de tabac d'un patient, il faut évaluer :</p><ul><li>Le <strong>mode</strong> de consommation (avec ses équivalences)</li><li>L'<strong><span class=\"nc-blue_bg\">âge de début</span></strong></li><li>La <strong>durée</strong> du tabagisme</li><li>La <strong>quantité</strong> consommée</li></ul></div>"},{"i":"373fd0927a86","n":75,"o":"75-2","u":"Définition","t":"Connaître les principaux types de dépendance entraînés par le tabac et la façon d’évaluer cette dépendance","q":"Comment évalue-t-on les dépendances psychologique et comportementale au tabac ?","a":"<div class=\"notion-course\"><p>Les dépendances psychologique et comportementale au tabac s'apprécient sur la <span class=\"nc-blue_bg\">présence de </span><strong><span class=\"nc-blue_bg\">craving</span></strong>, qui représente un facteur de risque de rechute.</p><ul><li>La <strong>dépendance psychologique</strong> est liée aux « effets positifs » associés à la cigarette (<span class=\"nc-green nc-bold\">se relaxer</span>, <span class=\"nc-green nc-bold\">réfléchir</span>, <span class=\"nc-green nc-bold\">effet coupe-faim</span>).</li><li>La <strong><span class=\"nc-purple_bg\">dépendance</span> comportementale (sociale)</strong> est liée aux <span class=\"nc-yellow_bg nc-bold\">situations répétées associées à la cigarette</span> (moments de convivialité, association au café, à l'<span class=\"nc-red_bg\">alcool</span>, au <span class=\"nc-red_bg\">cannabis</span>) déclenchant une envie « réflexe ».</li></ul></div>"},{"i":"37f7fa9f7dff","n":75,"o":"75-2","u":"Définition","t":"Connaître les principaux types de dépendance entraînés par le tabac et la façon d’évaluer cette dépendance","q":"Comment la dépendance au tabac est-elle définie selon la CIM-10 ?","a":"<div class=\"notion-course\"><p>Selon la CIM-10, la <span class=\"nc-purple_bg\">dépendance</span> au tabac est définie par la présence d'au moins <strong>3 manifestations au cours de la dernière année</strong>. Ces manifestations incluent :</p><ul><li>Un désir compulsif de consommer.</li><li>Des difficultés à contrôler l'usage (début, quantité, arrêt).</li><li>Un syndrome de sevrage à l'arrêt.</li><li>Une tolérance (augmentation des doses).</li><li>Un désintérêt pour les autres plaisirs.</li><li>Une poursuite de la consommation malgré les conséquences néfastes.</li></ul></div>"},{"i":"62695f1ddaa6","n":75,"o":"75-2","u":"Définition","t":"Connaître les principaux types de dépendance entraînés par le tabac et la façon d’évaluer cette dépendance","q":"Quels sont les principaux types de dépendance entraînés par le tabac ?","a":"<div class=\"notion-course\"><p>Le tabac entraîne plusieurs types de dépendance, qu'il faut évaluer :</p><ul><li>La <strong><span class=\"nc-purple_bg\">dépendance</span> physique (pharmacologique)</strong>.</li><li>La <strong><span class=\"nc-purple_bg\">dépendance</span> psychologique</strong>.</li><li>La <strong><span class=\"nc-purple_bg\">dépendance</span> comportementale (sociale)</strong>.</li></ul></div>"},{"i":"eebff1e1b8fa","n":75,"o":"75-2","u":"Définition","t":"Connaître les principaux types de dépendance entraînés par le tabac et la façon d’évaluer cette dépendance","q":"Comment évalue-t-on la dépendance physique au tabac et quel est son mécanisme ?","a":"<div class=\"notion-course\"><p>La dépendance physique au tabac, liée directement à la nicotine, s'évalue principalement par le <strong><span class=\"nc-blue_bg\">test de Fagerström</span></strong>. Son mécanisme implique :</p><ul><li>Un pic de concentration rapide de nicotine au cerveau (<strong>« <span class=\"nc-red nc-bold\">effet shoot</span> »</strong>).</li><li>La fixation de la nicotine sur les <strong><span class=\"nc-purple nc-bold\">récepteurs cholinergiques nicotiniques</span></strong>.</li><li>La stimulation du <strong>système de récompense</strong> par libération de dopamine.</li></ul></div>"},{"i":"a29a15767ced","n":75,"o":"75-20","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic de la dépendance","q":"Comment la dépendance au tabac est-elle médicalement diagnosticable en tenant compte des trois registres principaux ?","a":"<div class=\"notion-course\"><p>Le diagnostic de dépendance au tabac repose sur l'évaluation de trois registres :</p><ul><li>La <strong><span class=\"nc-purple_bg\">dépendance</span> pharmacologique</strong>.</li><li>La <strong><span class=\"nc-purple_bg\">dépendance</span> psychologique</strong>.</li><li>La <strong><span class=\"nc-purple_bg\">dépendance</span> comportementale</strong>.</li></ul></div>"},{"i":"a8bb4e36ba7a","n":75,"o":"75-20","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic de la dépendance","q":"Comment la dépendance psychologique et comportementale au tabac est-elle évaluée ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-purple_bg\">dépendance</span> psychologique et comportementale est évaluée par la <strong><span class=\"nc-blue_bg\">présence de craving</span></strong> (ou envie irrépressible de fumer), qui est un facteur de risque important de rechute.</p></div>"},{"i":"ad9029e0e415","n":75,"o":"75-20","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic de la dépendance","q":"Comment évalue-t-on le niveau de dépendance au tabac à l'aide de la version simplifiée du Test de Fagerström ?","a":"<div class=\"notion-course\"><p>La version simplifiée du <span class=\"nc-blue_bg\">Test de Fagerström</span> attribue un score en fonction de deux questions :</p><ul><li><strong>Nombre de cigarettes par jour :</strong></li><ul><li>≤ 10 → 0 point</li><li>11-20 → 1 point</li><li>21-30 → 2 points</li><li>≥ 31 → 3 points</li></ul><li><strong>Délai entre le réveil et la 1ère cigarette :</strong></li><ul><li>≤ 5 min → 3 points</li><li>6-30 min → 2 points</li><li>31-60 min → 1 point</li><li>&gt; 60 min → 0 point</li></ul></ul><p>L'<strong>interprétation</strong> du score total (version simplifiée) est la suivante :</p><ul><li><strong>0-1</strong> : non dépendant</li><li><strong>2-3</strong> : dépendance modérée</li><li><strong>4-6</strong> : dépendance forte</li></ul></div>"},{"i":"f852fc2fbad7","n":75,"o":"75-20","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic de la dépendance","q":"Quel outil est spécifiquement utilisé pour évaluer la dépendance pharmacologique au tabac et quelles sont ses caractéristiques principales ?","a":"<div class=\"notion-course\"><p><span class=\"nc-blue_bg nc-bold\">Fagerström</span> complet : six questions, 0–10. Simplifié : deux questions (quantité quotidienne et délai réveil–première cigarette), 0–6.</p></div>"},{"i":"0aafcc0f1602","n":75,"o":"75-21","u":"Diagnostic positif","t":"Connaître les signes de sevrage en tabac","q":"Quels sont les signes cliniques du syndrome de sevrage tabagique concernant l'humeur et le sommeil ?","a":"<div class=\"notion-course\"><ul><li><strong>Humeur</strong> : <span class=\"nc-orange_bg\">Humeur dépressive</span>, <span class=\"nc-blue_bg\">irritabilité, frustration, colère</span>.</li><li><strong>Sommeil</strong> : <span class=\"nc-orange_bg\">Insomnie</span>.</li></ul></div>"},{"i":"6b0320bf445a","n":75,"o":"75-21","u":"Diagnostic positif","t":"Connaître les signes de sevrage en tabac","q":"Quelle est l'origine du syndrome de sevrage tabagique et quel est son impact principal sur l'arrêt du tabac ?","a":"<div class=\"notion-course\"><p>Le syndrome de sevrage tabagique est consécutif au <strong>manque de nicotine</strong>. Il constitue le <strong><span class=\"nc-red nc-bold\">facteur de rechute principal</span></strong> après un arrêt brutal ou une diminution significative de la consommation de tabac.</p></div>"},{"i":"de4af2b64480","n":75,"o":"75-21","u":"Diagnostic positif","t":"Connaître les signes de sevrage en tabac","q":"Quels sont les signes cliniques du syndrome de sevrage tabagique concernant les fonctions cognitives et l'appétit ?","a":"<div class=\"notion-course\"><ul><li><strong>Cognitif</strong> : <span class=\"nc-orange_bg\">Anxiété</span>, <span class=\"nc-blue_bg\">difficultés de concentration</span>.</li><li><strong>Appétit / poids</strong> : <span class=\"nc-blue_bg\">Augmentation de l'appétit</span>, <span class=\"nc-orange_bg\">prise de poids</span>.</li></ul></div>"},{"i":"305edada04cf","n":75,"o":"75-22","u":"Diagnostic positif","t":"Connaître les complications médicales non psychiatriques","q":"Quelles sont les principales localisations de cancers causés par l'addiction au tabac ?","a":"<div class=\"notion-course\"><p>Poumon, VADS, œsophage, <span class=\"nc-red\">estomac</span>, <span class=\"nc-red\">foie</span>, <span class=\"nc-red\">pancréas</span>, colorectal, rein, <span class=\"nc-red\">vessie</span>, col utérin et leucémie myéloïde ; associations variables selon histologie.</p></div>"},{"i":"3d9b765138bf","n":75,"o":"75-22","u":"Diagnostic positif","t":"Connaître les complications médicales non psychiatriques","q":"Quelles sont les complications liées à l'addiction au tabac survenant pendant la grossesse et les atteintes dermatologiques associées ?","a":"<div class=\"notion-course\"><p><span class=\"nc-green nc-bold\">Grossesse</span> : fausse couche, <span class=\"nc-orange_bg\">GEU</span>, complications placentaires, prématurité, retard de croissance et mort fœtale. Peau : vieillissement et cicatrisation altérée. Buerger est une atteinte vasculaire.</p></div>"},{"i":"9dc5f347be31","n":75,"o":"75-22","u":"Diagnostic positif","t":"Connaître les complications médicales non psychiatriques","q":"Quelles sont les complications cardiovasculaires et respiratoires liées à l'addiction au tabac ?","a":"<div class=\"notion-course\"><p>Les complications cardiovasculaires et respiratoires liées à l'addiction au tabac comprennent :</p><ul><li><strong>Cardiovasculaires</strong> : <strong>IDM</strong> (Infarctus du Myocarde), <strong>AOMI</strong> (Artériopathie Oblitérante des Membres Inférieurs), <strong>AVC</strong> (Accident Vasculaire Cérébral), <strong>anévrisme de l'aorte abdominale</strong>, <strong>HTA</strong> (Hypertension Artérielle).</li><li><strong>Respiratoires</strong> : <strong><span class=\"nc-orange_bg\">BPCO</span></strong> (Broncho-Pneumopathie Chronique Obstructive) évoluant vers l'insuffisance respiratoire sans sevrage, <strong><span class=\"nc-orange_bg\">emphysème</span></strong>, <strong><span class=\"nc-orange_bg\">bronchite chronique</span></strong>, <strong><span class=\"nc-orange_bg\">asthme</span></strong> (exacerbations, mauvais contrôle).</li></ul></div>"},{"i":"4a2cb5cd0fd3","n":75,"o":"75-24","u":"Prise en charge","t":"Moment du sevrage : connaître la proposition d'aide à l'arrêt à chaque contact avec un professionnel de santé","q":"Quelle est l'approche recommandée pour la prise en charge de l'addiction au tabac lors de chaque contact avec un professionnel de santé, conformément aux recommandations de santé publique ?","a":"<div class=\"notion-course\"><p><span class=\"nc-red nc-bold\">Ask</span> : repérer ; <span class=\"nc-red nc-bold\">Advise</span> : conseiller ; <span class=\"nc-red nc-bold\">Assess</span> : évaluer ; <span class=\"nc-red nc-bold\">Assist</span> : aider ; <span class=\"nc-red nc-bold\">Arrange</span> : organiser le suivi. Une brochure ne remplace pas ce suivi.</p></div>"},{"i":"603ddb689910","n":75,"o":"75-24","u":"Prise en charge","t":"Moment du sevrage : connaître la proposition d'aide à l'arrêt à chaque contact avec un professionnel de santé","q":"Dans quelles situations spécifiques faut-il envisager un sevrage tabagique rapide chez un patient fumeur ?","a":"<div class=\"notion-course\"><p>Trois situations cliniques imposent d'envisager un sevrage tabagique rapide :</p><ul><li>La <strong><span class=\"nc-green nc-bold\">grossesse</span></strong>.</li><li>La <strong>découverte d'une maladie liée au tabac</strong>.</li><li>Une <strong>chirurgie programmée</strong> (un arrêt <strong>6 à 8 semaines</strong> avant l'intervention diminue significativement la morbi-mortalité opératoire).</li></ul></div>"},{"i":"21515c247d1d","n":75,"o":"75-25","u":"Prise en charge","t":"Connaître les moyens de prévention primaire et secondaire","q":"Quelles sont les mesures de prévention primaire de l'addiction au tabac dont l'efficacité a été universellement vérifiée ?","a":"<div class=\"notion-course\"><p>Les mesures dont l'efficacité a été universellement vérifiée incluent :</p><ul><li>Une <strong>augmentation forte et régulièrement répétée des prix</strong> du tabac.</li><li>L'<strong>interdiction de la publicité</strong>, qu'elle soit directe ou indirecte.</li><li>L'<strong>interdiction de fumer dans les <span class=\"nc-red nc-bold\">lieux publics clos</span> et les <span class=\"nc-red nc-bold\">lieux de travail</span></strong>.</li><li>L'<strong>interdiction de la vente de tabac aux moins de 18 ans</strong>.</li><li>L'apposition d'<strong>avertissements sanitaires illustrés sur les paquets</strong> de tabac.</li></ul></div>"},{"i":"459535703b02","n":75,"o":"75-25","u":"Prise en charge","t":"Connaître les moyens de prévention primaire et secondaire","q":"Citez les principales lois françaises qui ont encadré la prévention du tabagisme.","a":"<div class=\"notion-course\"><p>Les principales lois françaises encadrant le cadre légal de la prévention du tabagisme sont :</p><ul><li>La <strong>Loi Veil (1976)</strong>.</li><li>La <strong>Loi Évin (1991)</strong>.</li><li>Le <strong>Décret <span class=\"nc-blue\">Bertrand</span> (2006)</strong>.</li></ul></div>"},{"i":"f9403b20faaf","n":75,"o":"75-25","u":"Prise en charge","t":"Connaître les moyens de prévention primaire et secondaire","q":"Quel programme national encadre actuellement la lutte contre le tabac ?","a":"<div class=\"notion-course\"><p>PNLT 2023–2027 : prévention de l’entrée, accompagnement à l’arrêt, protection contre la fumée et action sur l’offre ; objectif génération sans tabac en 2032.</p></div>"},{"i":"6dc75d7849ff","n":75,"o":"75-26","u":"Prise en charge","t":"Connaître les traitements de la dépendance au tabac (pharmacologiques et non pharmacologiques)","q":"Quels sont les traitements pharmacologiques de première intention pour la dépendance au tabac ?","a":"<div class=\"notion-course\"><p><span class=\"nc-pink\">Substituts nicotiniques</span>, souvent patch + forme orale rapide, associés à l’accompagnement. La <span class=\"nc-pink_bg\">cigarette électronique</span> n’est pas un médicament.</p></div>"},{"i":"98d78d218e12","n":75,"o":"75-26","u":"Prise en charge","t":"Connaître les traitements de la dépendance au tabac (pharmacologiques et non pharmacologiques)","q":"Quels sont les effets indésirables classiques des substituts nicotiniques ?","a":"<div class=\"notion-course\"><p>Les effets indésirables sont généralement <span class=\"nc-green nc-bold\">modérés</span> et régressifs : <strong><span class=\"nc-yellow_bg\">céphalées</span></strong>, <strong><span class=\"nc-yellow_bg\">palpitations</span></strong>, <strong><span class=\"nc-blue_bg\">érythème</span></strong> ou <strong><span class=\"nc-blue_bg\">prurit</span></strong><span class=\"nc-blue_bg\"> au point d'application</span> pour les <span class=\"nc-blue_bg\">formes transdermiques</span>, et <strong>troubles <span class=\"nc-blue nc-bold\">buccaux</span></strong> pour les <span class=\"nc-blue_bg\">formes orales</span>.</p></div>"},{"i":"a02c67c3dce7","n":75,"o":"75-26","u":"Prise en charge","t":"Connaître les traitements de la dépendance au tabac (pharmacologiques et non pharmacologiques)","q":"Quels sont les traitements pharmacologiques de seconde et dernière intention pour la dépendance au tabac, en dehors des substituts nicotiniques ?","a":"<div class=\"notion-course\"><p>En dehors des <span class=\"nc-pink\">substituts nicotiniques</span>, la <strong><span class=\"nc-pink\">varénicline</span></strong> est utilisée en seconde intention et le <strong><span class=\"nc-pink_bg\">bupropion</span></strong> en dernière intention.</p></div>"},{"i":"ac8da1a60eec","n":75,"o":"75-26","u":"Prise en charge","t":"Connaître les traitements de la dépendance au tabac (pharmacologiques et non pharmacologiques)","q":"Quel est le principe de dosage des substituts nicotiniques ?","a":"<div class=\"notion-course\"><p>Dose individualisée selon dépendance et symptômes. Le repère 1 cigarette ≈ <span class=\"nc-pink_bg nc-bold\">1 mg</span> est approximatif ; ajuster les formes et la durée, souvent plusieurs mois.</p></div>"},{"i":"e42704e9a84a","n":75,"o":"75-26","u":"Prise en charge","t":"Connaître les traitements de la dépendance au tabac (pharmacologiques et non pharmacologiques)","q":"Quelle est l'efficacité et les contre-indications des substituts nicotiniques ?","a":"<div class=\"notion-course\"><p>Ils améliorent les chances d’arrêt et réduisent le manque. Vérifier le RCP ; <span class=\"nc-green nc-bold\">grossesse</span> et maladie cardiovasculaire demandent une adaptation, sans les assimiler à une interdiction générale.</p></div>"},{"i":"eae5664ab455","n":75,"o":"75-26","u":"Prise en charge","t":"Connaître les traitements de la dépendance au tabac (pharmacologiques et non pharmacologiques)","q":"Quels sont les différents types de prise en charge pour la dépendance au tabac ?","a":"<div class=\"notion-course\"><p>La prise en charge de la dépendance au tabac associe des moyens non pharmacologiques et pharmacologiques.</p></div>"},{"i":"f32f5e89ee32","n":75,"o":"75-26","u":"Prise en charge","t":"Connaître les traitements de la dépendance au tabac (pharmacologiques et non pharmacologiques)","q":"Quelles sont les méthodes non pharmacologiques de prise en charge de la dépendance au tabac ?","a":"<div class=\"notion-course\"><ul><li>Le <strong>conseil minimal</strong>, pratiqué par tout professionnel de santé.</li><li>Les <strong>psychothérapies</strong> : <span class=\"nc-green_bg\">entretien motivationnel</span>, <span class=\"nc-green_bg\">psychothérapie de soutien</span>, et <span class=\"nc-green_bg\">thérapies cognitivo-comportementales</span> (TCC).</li><li>Les <strong>aides</strong> : <span class=\"nc-green_bg\">accompagnement téléphonique</span> (ex : <span class=\"nc-pink nc-bold\">Tabac Info Service</span>) ou <span class=\"nc-blue_bg\">consultation de tabacologie</span>.</li></ul></div>"},{"i":"f9ffa7cbf1ea","n":75,"o":"75-26","u":"Prise en charge","t":"Connaître les traitements de la dépendance au tabac (pharmacologiques et non pharmacologiques)","q":"Quelles sont les différentes formes de substituts nicotiniques et leurs modalités d'association ?","a":"<div class=\"notion-course\"><ul><li>Les <span class=\"nc-blue_bg\">formes </span><strong><span class=\"nc-blue_bg\">transdermiques</span></strong> (<span class=\"nc-blue nc-bold\">timbres</span>/<span class=\"nc-blue nc-bold\">patchs</span>) : elles peuvent être de 16h ou 24h.</li><li>Les <span class=\"nc-blue_bg\">formes </span><strong><span class=\"nc-blue_bg\">orales</span></strong> : <span class=\"nc-blue nc-bold\">gommes</span>, <span class=\"nc-blue nc-bold\">comprimés</span>, <span class=\"nc-blue nc-bold\">pastilles</span>, <span class=\"nc-blue nc-bold\">inhaleurs</span>, <span class=\"nc-blue nc-bold\">sprays</span>.</li></ul><p>Ces différentes formes peuvent être associées entre elles.</p></div>"},{"i":"1eba8cbc55ce","n":75,"o":"75-27","u":"Prise en charge","t":"Connaître les outils institutionnels (tabac info service)","q":"Qu'est-ce que Tabac Info Service ?","a":"<div class=\"notion-course\"><p><span class=\"nc-pink nc-bold\">Tabac Info Service</span> est une <strong><span class=\"nc-pink nc-bold\">ligne</span> d'<span class=\"nc-green_bg\">accompagnement téléphonique</span></strong> destinée à aider à l'arrêt du tabac.</p></div>"},{"i":"3f1633e59815","n":75,"o":"75-27","u":"Prise en charge","t":"Connaître les outils institutionnels (tabac info service)","q":"Les substituts nicotiniques sont-ils encore limités à un forfait de 150 € par an ?","a":"<div class=\"notion-course\"><p>Non : les produits inscrits sont remboursés sur prescription à 65 %, sans plafond annuel ; complément selon couverture.</p></div>"},{"i":"a256cea391bd","n":75,"o":"75-27","u":"Prise en charge","t":"Connaître les outils institutionnels (tabac info service)","q":"À qui s'adresse la consultation de tabacologie ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-blue_bg\">consultation de tabacologie</span> est destinée aux personnes rencontrant des <strong>difficultés à arrêter de consommer du tabac</strong>.</p></div>"},{"i":"1ec427a0c8ba","n":75,"o":"75-6","u":"Epidémiologie","t":"Connaître l’âge de début, le pourcentage de dépendants et la mortalité mondiale et française liée au tabac et les risques","q":"Quel est l'âge moyen du début de la consommation tabagique quotidienne en France, selon les données épidémiologiques ?","a":"<div class=\"notion-course\"><p>L'âge moyen du début d'une consommation quotidienne de tabac en France est d'environ <strong><span class=\"nc-pink nc-bold\">15 ans</span></strong>.</p></div>"},{"i":"5f854fc46c37","n":75,"o":"75-6","u":"Epidémiologie","t":"Connaître l’âge de début, le pourcentage de dépendants et la mortalité mondiale et française liée au tabac et les risques","q":"Quel pourcentage des fumeurs réguliers présente des signes de dépendance au tabac ?","a":"<div class=\"notion-course\"><p>Environ <strong>50 %</strong> des fumeurs réguliers présentent des signes de <span class=\"nc-purple_bg\">dépendance</span> au tabac.</p></div>"},{"i":"78909e8c2633","n":75,"o":"75-6","u":"Epidémiologie","t":"Connaître l’âge de début, le pourcentage de dépendants et la mortalité mondiale et française liée au tabac et les risques","q":"Quelle est la mortalité mondiale liée au tabac et quel pourcentage des fumeurs mourront prématurément de cette cause ?","a":"<div class=\"notion-course\"><p>Au niveau mondial, le tabac est responsable d'environ <strong>1 décès sur 10</strong>. Environ <strong>50 %</strong> des fumeurs mourront prématurément d'une maladie due au tabac.</p></div>"},{"i":"a2a7d8bc498d","n":75,"o":"75-6","u":"Epidémiologie","t":"Connaître l’âge de début, le pourcentage de dépendants et la mortalité mondiale et française liée au tabac et les risques","q":"Quelle est la mortalité annuelle en France liée au tabac et est-ce une cause évitable ?","a":"<div class=\"notion-course\"><p>Environ 68 000 décès attribuables en France en 2023, première cause de mortalité évitable. Ancienne estimation : 75 000 en 2015.</p></div>"},{"i":"effa3734f443","n":75,"o":"75-6","u":"Epidémiologie","t":"Connaître l’âge de début, le pourcentage de dépendants et la mortalité mondiale et française liée au tabac et les risques","q":"Quel est le facteur de risque le plus important de complications liées à l'intoxication tabagique et comment agit-il sur le risque de cancer ?","a":"<div class=\"notion-course\"><p>La durée d’exposition est majeure, avec l’intensité et le temps depuis l’arrêt. Pas de seuil sûr ni de multiplicateur universel applicable à une personne.</p></div>"},{"i":"7bd45e0f478f","n":75,"o":"75-8","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme chez les hommes et les femmes","q":"Quelles sont les tendances d'évolution du tabagisme observées chez les hommes et les femmes en France, notamment pour les différentes tranches d'âge ?","a":"<div class=\"notion-course\"><p>Tendance globale à la baisse sur la décennie, avec différences de génération et fluctuations. Comparer à population et méthode constantes.</p></div>"},{"i":"a033264aadb1","n":75,"o":"75-8","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme chez les hommes et les femmes","q":"Quelle est la prévalence globale de la consommation de tabac (toutes formes confondues) dans la population française âgée de 18 à 75 ans ?","a":"<div class=\"notion-course\"><p>Baromètre 2024 : 25,0 % chez les 18–75 ans de France hexagonale, dont 18,2 % quotidiennement.</p></div>"},{"i":"e9dded0911d7","n":75,"o":"75-8","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme chez les hommes et les femmes","q":"Comment la prévalence du tabagisme se distingue-t-elle entre les hommes et les femmes en France (18-75 ans), aussi bien pour la consommation globale que quotidienne ?","a":"<div class=\"notion-course\"><p>Quotidien en 2024, France hexagonale 18–75 ans : 20,4 % des hommes, 16,2 % des femmes. Ne pas mélanger avec les chiffres d’une autre année ou tranche d’âge.</p></div>"},{"i":"12da158d3c92","n":75,"o":"75-9","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme chez les jeunes","q":"Quelle est la tendance de l'expérimentation de la chicha chez les élèves de 3ᵉ entre 2018 et 2021 ?","a":"<div class=\"notion-course\"><p>L'expérimentation de la chicha chez les élèves de 3ᵉ est en <strong>recul</strong>, passant de <strong>26,2 % en 2018</strong> à <strong>20 % en 2021</strong>.</p></div>"},{"i":"695b922187e9","n":75,"o":"75-9","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme chez les jeunes","q":"Quelle est la tendance observée pour l'usage quotidien du tabac chez les élèves de 3ᵉ entre 2010 et 2021 ?","a":"<div class=\"notion-course\"><p>L'usage quotidien du tabac chez les élèves de 3ᵉ est passé de <strong>15,6 % en 2010</strong> à <strong>3,7 % en 2021</strong>.</p></div>"},{"i":"7376f24f5683","n":75,"o":"75-9","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme chez les jeunes","q":"Quelle est la tendance observée pour l'expérimentation du tabac chez les élèves de 3ᵉ entre 2010 et 2021 ?","a":"<div class=\"notion-course\"><p>L'expérimentation du tabac chez les élèves de 3ᵉ est passée de <strong>51,8 % en 2010</strong> à <strong>29,1 % en 2021</strong>.</p></div>"},{"i":"b7f3fae88a63","n":75,"o":"75-9","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme chez les jeunes","q":"Quelle est l'évolution récente de la consommation de tabac chez les jeunes en France ?","a":"<div class=\"notion-course\"><p>La consommation de tabac chez les jeunes est en <strong>baisse importante</strong>.</p></div>"},{"i":"d0ce10edd190","n":75,"o":"75-9","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme chez les jeunes","q":"Quelle est la part des élèves de 3ᵉ ayant déjà expérimenté la cigarette électronique en 2021 ?","a":"<div class=\"notion-course\"><p>En 2021, <strong>34,2 %</strong> des élèves de 3ᵉ ont expérimenté la <strong><span class=\"nc-pink_bg\">cigarette électronique</span></strong>.</p></div>"},{"i":"e859133075f6","n":75,"o":"75-3","u":"Définition","t":"Connaître la définition de la cigarette électronique","q":"La vapeur d’une cigarette électronique est-elle seulement de l’eau ?","a":"<div class=\"notion-course\"><ul><li>Non : aérosol de solvants, arômes, éventuellement nicotine et produits de chauffage ; <span class=\"nc-green nc-bold\">absence de combustion</span> ≠ innocuité.</li></ul></div>"},{"i":"c211fa619816","n":75,"o":"75-4","u":"Physiopathologie","t":"Connaître la toxicité de la nicotine, des goudrons et de la fumée de tabac","q":"Pourquoi substituts nicotiniques et cigarettes n’ont-ils pas la même toxicité ?","a":"<div class=\"notion-course\"><ul><li>Les substituts délivrent de la nicotine sans les produits de combustion, responsables de l’essentiel des dommages.</li></ul></div>"},{"i":"ba6566ecf1f5","n":75,"o":"75-5","u":"Physiopathologie","t":"Connaître le mécanisme d'atteinte artérielle (thrombogénicité, vasomotricité, inflammation)","q":"Quels mécanismes relient tabac et événements artériels ?","a":"<div class=\"notion-course\"><ul><li>Dysfonction endothéliale, activation <span class=\"nc-blue_bg nc-bold\">plaquettaire</span>, inflammation/athérome, vasoconstriction et hypoxie par le CO.</li></ul></div>"},{"i":"489666b4c632","n":75,"o":"75-7","u":"Epidémiologie","t":"Connaître les tendances épidémiologiques du tabagisme au cours du temps","q":"Pourquoi dater un chiffre de prévalence tabagique ?","a":"<div class=\"notion-course\"><ul><li>La période, l’âge, le territoire, la fréquence d’usage et la méthode d’enquête modifient son interprétation.</li></ul></div>"},{"i":"3ff71a25c250","n":75,"o":"75-18","u":"Epidémiologie","t":"Connaître les catégories socio-professionnelles (CSP) des fumeurs en France","q":"Quel gradient social concerne le tabagisme ?","a":"<div class=\"notion-course\"><ul><li>Prévalence plus élevée dans les populations socialement défavorisées ; adapter les aides et l’accès aux soins.</li></ul></div>"},{"i":"86704cc876dd","n":75,"o":"75-23","u":"Diagnostic positif","t":"Connaître le diagnostic des comorbidités psychiatriques et addictives","q":"Quelle interaction médicamenteuse anticiper à l’arrêt du tabac ?","a":"<div class=\"notion-course\"><ul><li>Levée de l’induction par la fumée, notamment augmentation possible de clozapine/olanzapine : surveillance et adaptation.</li></ul></div>"},{"i":"8bbce909fbc5","n":75,"o":"75-28","u":"Prise en charge","t":"Connaître les modalités de la prise en charge après un évènement aigu : infarctus du myocarde, décompensation respiratoire…","q":"Que préparer avant la sortie d’un fumeur hospitalisé pour un événement aigu ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-pink_bg\">Traitement</span> du manque, ordonnance, stratégie de prévention de la reprise et rendez-vous avec relais ambulatoire.</li></ul></div>"},{"i":"6caddab1dbbe","n":75,"o":"75-29","u":"Prise en charge","t":"Savoir rechercher des comorbidités en fonction du terrain","q":"Quels terrains nécessitent une prise en charge du tabac adaptée ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-green nc-bold\">Grossesse</span>, maladie cardiovasculaire/respiratoire, <span class=\"nc-red nc-bold\">trouble</span> psychiatrique, autres addictions et précarité.</li></ul></div>"},{"i":"c307663a77f4","n":75,"o":"75-30","u":"Prise en charge","t":"Connaître les modalités de la prise en charge à long terme : savoir que les rechutes sont la règle d'où la proposition systématique de l'arrêt du tabac","q":"Comment réagir à une reprise du tabac ?","a":"<div class=\"notion-course\"><ul><li>Sans blâme : analyser les déclencheurs, adapter le <span class=\"nc-pink_bg\">traitement</span> et proposer une nouvelle tentative.</li></ul></div>"},{"i":"fec7668fd398","n":75,"o":"75-31","u":"Prise en charge","t":"Connaître l’aide médicamenteuse autre que traitements substitutifs nicotiniques","q":"Quel risque majeur limite le bupropion ?","a":"<div class=\"notion-course\"><ul><li>Convulsions : rechercher épilepsie, anorexie/boulimie, sevrage brutal d’<span class=\"nc-red_bg\">alcool</span>/BZD et interactions.</li></ul></div>"},{"i":"b0a00f4cdafa","n":75,"o":"75-32","u":"Prise en charge","t":"Savoir quand adresser un patient en consultation de tabacologie","q":"Quand demander une consultation de tabacologie ?","a":"<div class=\"notion-course\"><ul><li>Difficultés répétées, forte dépendance, comorbidités ou terrain complexe, et demande du patient.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204","reviewedAt":"2026-10-14","note":"Cours, cartes et arbres relus. Couleurs des passages Notion correspondants ; références et compléments identifiés dans chaque objectif.","sddStatus":"Situations LiSA vérifiées le 14 octobre 2026 dans la session UNESS connectée.","algorithms":2,"lisaSituations":[{"number":314,"title":"Prévention des risques liés au tabac","url":"https://livret.uness.fr/lisa/2026/Pr%C3%A9vention_des_risques_li%C3%A9s_au_tabac_SDD-314","expectations":["Évaluer exposition et dépendance, expliquer les risques actifs, passifs et pendant la grossesse ; chercher co-addictions et complications.","Adapter aides médicamenteuses et accompagnement, organiser le suivi et l’orientation ; prévenir l’initiation et les reprises."],"verifiedAt":"2026-10-14"},{"number":292,"title":"Première consultation d’addictologie","url":"https://livret.uness.fr/lisa/2026/Premi%C3%A8re_consultation_d%27addictologie_SDD-292","expectations":["Caractériser usage nocif, dépendance ou addiction comportementale selon la classification utilisée ; rechercher sevrage, complications et comorbidités.","Évaluer les conséquences familiales, sociales et professionnelles, fixer des objectifs partagés et orienter ou proposer une substitution selon indication."],"verifiedAt":"2026-10-14"},{"number":293,"title":"Consultation de suivi addictologie","url":"https://livret.uness.fr/lisa/2026/Consultation_de_suivi_addictologie_SDD-293","expectations":["Rechercher manque, nouveaux symptômes, complications et comorbidités ; apprécier efficacité, tolérance et qualité de vie.","Adapter prescription et accompagnement social ; la valorisation du stage inclut psychothérapie, entretien motivationnel et soutien des proches avec respect de la confidentialité."],"verifiedAt":"2026-10-14"}]},"liensGlobaux":[{"href":"https://app.notion.com/p/2ad37f85d94181368378d1ac0deecf7b?pvs=204","label":"Ton cours Notion ↗"},{"href":"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf","label":"CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024) ↗"},{"href":"https://www.ameli.fr/assure/remboursements/rembourse/medicaments-vaccins-dispositifs-medicaux/prise-charge-substituts-nicotiniques","label":"Assurance maladie · Prise en charge des substituts nicotiniques ↗"},{"href":"https://www.santepubliquefrance.fr/tabac","label":"Santé publique France · Tabac : mortalité attribuable ↗"},{"href":"https://www.drogues.gouv.fr/sites/default/files/2025-10/Barom%C3%A8tre_Tabagisme_2024.pdf","label":"Santé publique France · Baromètre tabagisme 2024 ↗"},{"href":"https://beh.santepubliquefrance.fr/beh/2018/35-36/2018_35-36_2.html","label":"Santé publique France · Tabac pendant la grossesse, enquête 2016 ↗"},{"href":"https://www.cancer.fr/toute-l-information-sur-les-cancers/comprendre-les-cancers/les-facteurs-de-risque/barometre-cancer/tabac-et-cancer","label":"INCa · Tabac et cancer ↗"},{"href":"https://www.has-sante.fr/jcms/c_1718021/fr/","label":"HAS · Arrêt du tabac : recommandations et algorithmes ↗"},{"href":"https://sante.gouv.fr/IMG/pdf/plan_national_contre_le_tabac.pdf","label":"Ministère de la Santé · Programme national de lutte contre le tabac 2023–2027 ↗"},{"href":"https://www.info.gouv.fr/actualite/interdiction-de-fumer-de-nouveaux-lieux-concernes-cet-ete","label":"Gouvernement · Extension des espaces sans tabac en 2025 ↗"}]};
